const lessons = [
  {"num": 1, "time": "00:00:30,000 --> 00:00:34,579", "arabic": "اَلسَّلَامُ عَلَى أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Mo'minlar amiriga salom bo'lsin.", "note": null},
  {"num": 2, "time": "00:00:34,579 --> 00:00:38,219", "arabic": "وَعَلَيْكَ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga ham salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 3, "time": "00:00:38,219 --> 00:00:39,859", "arabic": "أَرْسَلْتَ فِي طَلَبِي", "segs": null, "full_uz": "Meni chaqirtirgan ekansiz.", "note": null},
  {"num": 4, "time": "00:01:01,000 --> 00:01:03,000", "arabic": "كَيْفَ حَالُكِ يَا أُمَّهْ؟", "segs": null, "full_uz": "Ahvolingiz qalay, onajon?", "note": null},
  {"num": 5, "time": "00:01:07,000 --> 00:01:11,000", "arabic": "بَارَكَ اللَّهُ فِيكَ بِخَيْرٍ وَالْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Alloh sizni barakali qilsin, yaxshiman, Allohga hamdlar bo'lsin.", "note": null},
  {"num": 6, "time": "00:01:18,000 --> 00:01:20,000", "arabic": "وَكَيْفَ رِضَاكِ عَنِّي يَا أُمِّي؟", "segs": null, "full_uz": "Mendan roziligingiz qalay, onajon?", "note": null},
  {"num": 7, "time": "00:01:27,000 --> 00:01:29,000", "arabic": "وَكَيْفَ يَكُونُ قَلْبُ الْأُمِّ عَلَى وَلَدِهَا؟", "segs": null, "full_uz": "Onaning qalbi o'z farzandiga qanday bo'lishi mumkin?", "note": null},
  {"num": 8, "time": "00:01:30,000 --> 00:01:33,840", "arabic": "إِلَّا الدُّعَاءَ لَهُ بِالتَّوْفِيقِ وَالسَّدَادِ بُكْرَةً وَعَشِيَّةً", "segs": null, "full_uz": "Faqat ertayu kech unga muvaffaqiyat va to'g'ri yo'l uchun duo qilishdan boshqa narsa emas.", "note": null},
  {"num": 9, "time": "00:01:33,840 --> 00:01:38,359", "arabic": "أَطَالَ اللَّهُ فِي عُمْرِكَ", "segs": null, "full_uz": "Alloh umringizni uzun qilsin.", "note": null},
  {"num": 10, "time": "00:01:38,359 --> 00:01:42,939", "arabic": "وَأَخَذَ بِيَدِكَ لِمَا يُحِبُّهُ وَيَرْضَاهُ", "segs": null, "full_uz": "Va O'zi yoqtirgan va rozi bo'ladigan yo'lda qo'lingizdan tutsin.", "note": null},
  {"num": 11, "time": "00:02:00,000 --> 00:02:10,719", "arabic": "قُلْتُ لِنَفْسِي أَرَى أُمِّي قَبْلَ الِانْغِمَاسِ فِي شُؤُونِ الدِّيوَانِ وَأَعْمَالِ الْحُجَّةِ", "segs": [{"ar": "قُلْتُ لِنَفْسِي أَرَى أُمِّي", "uz": "o'z-o'zimga, onamni ko'rib qo'yay, dedim"}, {"ar": "قَبْلَ الِانْغِمَاسِ فِي شُؤُونِ الدِّيوَانِ وَأَعْمَالِ الْحُجَّةِ", "uz": "devon ishlariga va hujjat-yorliqlarga cho'mib ketishdan oldin"}], "full_uz": "O'z-o'zimga, devon ishlariga va hujjatlarga cho'mib ketishdan oldin onamni ko'rib qo'yay, dedim.", "note": null},
  {"num": 12, "time": "00:02:10,719 --> 00:02:15,360", "arabic": "إِنَّ الرَّعِيَّةَ أَمَانَةٌ فِي عُنُقِكَ", "segs": null, "full_uz": "Raiyat (fuqaro) — bo'yningizdagi omonatdir.", "note": null},
  {"num": 13, "time": "00:02:15,360 --> 00:02:18,939", "arabic": "قَدْ كَانَ وَالِدُكَ رَحِمَهُ اللَّهُ", "segs": null, "full_uz": "Otangiz, Alloh unga rahm qilsin.", "note": null},
  {"num": 14, "time": "00:02:18,939 --> 00:02:21,639", "arabic": "يَتَخَوَّلُهُمْ بِرِعَايَتِهِ", "segs": null, "full_uz": "Ularni o'z g'amxo'rligi bilan vaqti-vaqti bilan kuzatib turardi.", "note": null},
  {"num": 15, "time": "00:02:21,639 --> 00:02:24,400", "arabic": "كَمَا يَتَخَوَّلُ الْوَالِدُ ابْنَهُ", "segs": null, "full_uz": "Xuddi ota o'z o'g'lini vaqti-vaqti bilan tarbiyalab, kuzatib turgani kabi.", "note": null},
  {"num": 16, "time": "00:02:26,800 --> 00:02:28,819", "arabic": "رَحِمَ اللَّهُ أَبَا جَعْفَرٍ", "segs": null, "full_uz": "Alloh Abu Ja'farga rahm qilsin.", "note": null},
  {"num": 17, "time": "00:02:28,819 --> 00:02:32,259", "arabic": "مَنْ مِنَّا يَقْوَى عَلَى مَا كَانَ يَقْوَى عَلَيْهِ؟", "segs": null, "full_uz": "Qaysimiz u qodir bo'lgan narsaga qodir bo'lardik?", "note": null},
  {"num": 18, "time": "00:02:32,259 --> 00:02:36,180", "arabic": "وَفَّقَكَ اللَّهُ لِلسَّيْرِ عَلَى خُطَاهُ", "segs": null, "full_uz": "Alloh sizga uning izidan yurishga tavfiq bersin.", "note": null},
  {"num": 19, "time": "00:02:36,180 --> 00:02:40,000", "arabic": "وَجَعَلَكَ خَيْرَ أَخْلَافٍ مِنْ خَيْرِ سَلَفٍ", "segs": null, "full_uz": "Va sizni yaxshi ajdoddan kelgan yaxshi avlod qilsin.", "note": null},
  {"num": 20, "time": "00:02:40,000 --> 00:02:47,859", "arabic": "رَحِمَ اللَّهُ أَخَاكَ الْأَمِينَ", "segs": null, "full_uz": "Alloh birodaringiz Aminga rahm qilsin.", "note": null},
  {"num": 21, "time": "00:02:47,859 --> 00:02:51,699", "arabic": "وَغَفَرَ لَهُ", "segs": null, "full_uz": "Va uni mag'firat qilsin.", "note": null},
  {"num": 22, "time": "00:02:54,759 --> 00:02:57,599", "arabic": "اَلْحَمْدُ لِلَّهِ عَلَى مَا قَضَى وَحَكَمَ", "segs": null, "full_uz": "Alloh hukm qilgan va taqdir etgan narsaga hamdlar bo'lsin.", "note": null},
  {"num": 23, "time": "00:02:57,599 --> 00:03:24,459", "arabic": "لَا أَدْرِي لِمَاذَا تُشْغِلُ بَالَكَ بِمَا لَا يَجُرُّ عَلَيْكَ إِلَّا الضِّيقَةَ وَالْحُزْنَ", "segs": [{"ar": "لَا أَدْرِي لِمَاذَا تُشْغِلُ بَالَكَ", "uz": "nega o'zingni band qilib yurasan, bilmadim"}, {"ar": "بِمَا لَا يَجُرُّ عَلَيْكَ إِلَّا الضِّيقَةَ وَالْحُزْنَ", "uz": "senga faqat tang holat va g'am-g'ussa keltiradigan narsa bilan"}], "full_uz": "Senga faqat tang holat va g'am-g'ussa keltiradigan narsa bilan nega o'zingni band qilib yurasan, bilmadim.", "note": null},
  {"num": 24, "time": "00:03:24,460 --> 00:03:27,840", "arabic": "أَأَنْتَ تَقُولِينَ هَذَا يَا فَوْزُ؟", "segs": null, "full_uz": "Shuni siz aytyapsizmi, Fawz?", "note": null},
  {"num": 25, "time": "00:03:27,840 --> 00:03:32,219", "arabic": "إِذَنْكَ لَمْ تُفْنِ عُمْرَكَ فِي خِدْمَةِ السُّلْطَانِ وَأَبْنَائِهِ", "segs": null, "full_uz": "Axir siz umringizni sulton va uning farzandlariga xizmat qilishga sarflamadingizmi?", "note": null},
  {"num": 26, "time": "00:03:32,219 --> 00:03:38,319", "arabic": "ثُمَّ تَرَيْنَ ثَمَرَةَ ذَلِكَ تَذْهَبُ إِلَى أُنَاسٍ لَمْ يَكُونُوا إِلَّا خَدَمًا وَصُنَّاعًا بَيْنَ أَيْدِينَا", "segs": [{"ar": "ثُمَّ تَرَيْنَ ثَمَرَةَ ذَلِكَ تَذْهَبُ إِلَى أُنَاسٍ", "uz": "keyin esa uning mevasi boshqa odamlarga ketayotganini ko'rasiz"}, {"ar": "لَمْ يَكُونُوا إِلَّا خَدَمًا وَصُنَّاعًا بَيْنَ أَيْدِينَا", "uz": "holbuki, ular bizning qo'limiz ostida xizmatkor va hunarmanddan boshqa narsa emas edilar"}], "full_uz": "Keyin esa uning mevasi, bizning qo'limiz ostida xizmatkor va hunarmanddan boshqa narsa bo'lmagan odamlarga ketayotganini ko'rasiz.", "note": null},
  {"num": 27, "time": "00:03:38,319 --> 00:03:44,580", "arabic": "لَا تُبَالِغْ يَا أَبَا الْجَحْجَاحِ", "segs": null, "full_uz": "Ortiqcha bo'rttirma, Abul Jahjoh.", "note": null},
  {"num": 28, "time": "00:03:44,580 --> 00:03:46,360", "arabic": "وَاغْفِرْ لِي قَوْلِي هَذَا", "segs": null, "full_uz": "Va shu gapim uchun meni kechir.", "note": null},
  {"num": 29, "time": "00:03:46,360 --> 00:03:49,200", "arabic": "إِنَّكَ تَحْمِلُ الْأُمُورَ فَوْقَ مَا لَا تُطِيقُ", "segs": null, "full_uz": "Sen ishlarni ko'tara olmaydigan darajada og'ir olyapsan.", "note": null},
  {"num": 30, "time": "00:03:49,200 --> 00:03:51,159", "arabic": "وَكَيْفَ ذَلِكَ يَا فَوْزُ؟", "segs": null, "full_uz": "Bu qanday, Fawz?", "note": null},
  {"num": 31, "time": "00:03:51,159 --> 00:03:53,460", "arabic": "مَا يُعَذِّبُكَ وَيُنَغِّصُ عَلَيْكَ أَيَّامَكَ", "segs": null, "full_uz": "Seni azoblab, kunlaringni zaharlab yuborayotgan narsa.", "note": null},
  {"num": 32, "time": "00:03:53,460 --> 00:03:56,040", "arabic": "هُوَ إِحْسَاسُكَ بِالْخِذْلَانِ وَنُكْرَانِ الْجَمِيلِ", "segs": null, "full_uz": "Bu — o'zingni tashlab qo'yilgan va yaxshiligingni tan olmagan his qilishingdir.", "note": null},
  {"num": 33, "time": "00:03:56,040 --> 00:04:00,800", "arabic": "أَيْ أَنَّكَ تَحْتَكِمُ بِعَلَاقَتِكَ مَعَ السُّلْطَانِ لِلْعَوَاطِفِ وَالْمَشَاعِرِ", "segs": null, "full_uz": "Ya'ni sen sulton bilan bo'lgan munosabatingda tuyg'u va his-hayajonlarga tayanasan.", "note": null},
  {"num": 34, "time": "00:04:00,800 --> 00:04:05,800", "arabic": "بَيْنَمَا السُّلْطَانُ لَا يَحْتَكِمُ بِعَلَاقَتِهِ مَعَ الْآخَرِينَ لِلْعَوَاطِفِ وَالْمَشَاعِرِ", "segs": null, "full_uz": "Holbuki, sulton boshqalar bilan bo'lgan munosabatida tuyg'u va his-hayajonlarga tayanmaydi.", "note": null},
  {"num": 35, "time": "00:04:05,800 --> 00:04:09,640", "arabic": "بَلْ يَحْتَكِمُ لِلْمَصَالِحِ وَيُقَرِّبُ مَنْ يَخْدُمُهُ", "segs": null, "full_uz": "Balki manfaatlarga tayanadi va o'ziga xizmat qiladiganlarni yaqinlashtiradi.", "note": null},
  {"num": 36, "time": "00:04:09,640 --> 00:04:12,659", "arabic": "وَيَبْدُو أَنَّكَ لَمْ تَعُدْ تَخْدُمُ مَا يُرِيدُونَ", "segs": null, "full_uz": "Va ko'rinishidan, sen endi ular istagan narsaga xizmat qilmay qo'ygansan.", "note": null},
  {"num": 37, "time": "00:04:12,659 --> 00:04:16,460", "arabic": "لِذَلِكَ يُهَمِّشُونَكَ وَيُبْعِدُونَكَ عَنِ الْمَنَاصِبِ الْحَسَّاسَةِ", "segs": null, "full_uz": "Shu bois seni chetlab, muhim lavozimlardan uzoqlashtirishmoqda.", "note": null},
  {"num": 38, "time": "00:04:16,460 --> 00:04:19,620", "arabic": "وَإِنْ أَرَدْتَ رَأْيِي فَهَذَا أَفْضَلُ لَكَ", "segs": null, "full_uz": "Fikrimni istasang, bu sen uchun yaxshiroqdir.", "note": null},
  {"num": 39, "time": "00:04:19,620 --> 00:04:21,540", "arabic": "غَادِرْهُمْ قَبْلَ أَنْ يَطْرُدُوكَ", "segs": null, "full_uz": "Ular seni haydashidan oldin, o'zing ket.", "note": null},
  {"num": 40, "time": "00:04:23,459 --> 00:04:32,099", "arabic": "قَدْ تَكُونِينَ عَلَى حَقٍّ يَا فَوْزُ", "segs": null, "full_uz": "Ehtimol, sen haqsan, Fawz.", "note": null},
  {"num": 41, "time": "00:04:32,099 --> 00:04:37,199", "arabic": "قَدْ تَكُونِينَ عَلَى حَقٍّ", "segs": null, "full_uz": "Ehtimol, sen haqsan.", "note": null},
  {"num": 42, "time": "00:04:37,199 --> 00:04:42,139", "arabic": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ", "segs": null, "full_uz": "Bismillahir Rohmanir Rohim.", "note": null},
  {"num": 43, "time": "00:04:42,139 --> 00:04:44,679", "arabic": "مَا شَاءَ اللَّهُ وَالْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Mashaalloh, Allohga hamdlar bo'lsin.", "note": null},
  {"num": 44, "time": "00:04:49,439 --> 00:04:52,919", "arabic": "كَيْفَ تَجِدِينَ نَفْسَكِ الْيَوْمَ يَا عَبَّاسَةُ؟", "segs": null, "full_uz": "Bugun o'zingizni qanday his qilyapsiz, Abbasa?", "note": null},
  {"num": 45, "time": "00:04:52,920 --> 00:04:57,800", "arabic": "اَلْحَمْدُ لِلَّهِ أَنَا بِخَيْرٍ مَا دُمْتَ أَنْتَ بِخَيْرٍ", "segs": null, "full_uz": "Allohga hamdlar bo'lsin, siz yaxshi ekansiz, men ham yaxshiman.", "note": null},
  {"num": 46, "time": "00:04:57,800 --> 00:05:00,920", "arabic": "وَكَيْفَ حَالُ هَذَا الْفَتَى الشَّيْبَانِيِّ؟", "segs": null, "full_uz": "Bu Shayboniy yigitchaning ahvoli qalay?", "note": null},
  {"num": 47, "time": "00:05:02,360 --> 00:05:06,319", "arabic": "كَمَا تَرَى إِنَّهُ بِخَيْرٍ وَالْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Ko'rib turganingizdek, u yaxshi, Allohga hamdlar bo'lsin.", "note": null},
  {"num": 48, "time": "00:05:06,319 --> 00:05:07,259", "arabic": "اَلْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Allohga hamdlar bo'lsin.", "note": null},
  {"num": 49, "time": "00:05:07,259 --> 00:05:10,920", "arabic": "لَمْ تَقُلْ لِي مَاذَا سَتُسَمِّيهِ؟", "segs": null, "full_uz": "Unga qanday ism qo'yishingizni aytmadingiz-ku?", "note": null},
  {"num": 50, "time": "00:05:15,180 --> 00:05:15,660", "arabic": "صَالِحٌ", "segs": null, "full_uz": "Solih.", "note": null},
  {"num": 51, "time": "00:05:15,660 --> 00:05:21,600", "arabic": "اِسْمُهُ صَالِحٌ لَعَلَّهُ يَكُونُ جَدِيرًا بِهَذَا الِاسْمِ", "segs": null, "full_uz": "Ismi Solih, ehtimol shu ismga munosib bo'lar.", "note": null},
  {"num": 52, "time": "00:05:21,600 --> 00:05:26,740", "arabic": "صَالِحٌ نِعْمَ مَا اخْتَرْتَ يَا أَبَا صَالِحٍ", "segs": null, "full_uz": "Solih — juda yaxshi tanlagansiz, Abu Solih.", "note": null},
  {"num": 53, "time": "00:05:26,740 --> 00:05:40,780", "arabic": "أَلَا يَكْفِي أَنَّ أَمِيرَ الْمُؤْمِنِينَ سَمَحَ لَهُمْ أَنْ يَنْشُرُوا الْمُعْتَقَدَاتِ الْفَاسِدَةَ وَالْآرَاءَ الشَّاذَّةَ؟", "segs": [{"ar": "أَلَا يَكْفِي أَنَّ أَمِيرَ الْمُؤْمِنِينَ سَمَحَ لَهُمْ", "uz": "mo'minlar amirining ularga ruxsat berishi yetarli emasmi"}, {"ar": "أَنْ يَنْشُرُوا الْمُعْتَقَدَاتِ الْفَاسِدَةَ وَالْآرَاءَ الشَّاذَّةَ؟", "uz": "buzuq e'tiqodlar va g'ayrioddiy fikrlarni tarqatishlariga?"}], "full_uz": "Mo'minlar amirining ularga buzuq e'tiqodlar va g'ayrioddiy fikrlarni tarqatishga ruxsat berishi yetarli emasmi?", "note": null},
  {"num": 54, "time": "00:05:40,780 --> 00:05:49,600", "arabic": "غَرِيبٌ غَرِيبٌ أَمْرُ هَؤُلَاءِ الْقَوْمِ لَا يَعْرِفُونَ مِنَ الدِّينِ إِلَّا الْقُشُورَ", "segs": [{"ar": "غَرِيبٌ غَرِيبٌ أَمْرُ هَؤُلَاءِ الْقَوْمِ", "uz": "G'alati, g'alati bu qavmning ishi"}, {"ar": "لَا يَعْرِفُونَ مِنَ الدِّينِ إِلَّا الْقُشُورَ", "uz": "ular dindan faqat po'stlog'ini bilishadi"}], "full_uz": "G'alati, g'alati bu qavmning ishi — ular dindan faqat po'stlog'ini bilishadi.", "note": null},
  {"num": 55, "time": "00:05:49,600 --> 00:05:54,240", "arabic": "وَحِينَ يَتَصَدَّى إِخْوَتُهُمْ لِلزَّنَادِقَةِ وَالْمُلْحِدِينَ", "segs": null, "full_uz": "Va birodarlari zindiq va dahriylarga qarshi chiqqanida.", "note": null},
  {"num": 56, "time": "00:05:54,240 --> 00:05:58,800", "arabic": "وَيُبَيِّنُونَ لِلنَّاسِ مَا غَابَ عَنْهُمْ مِنْ أُمُورِ الدِّينِ", "segs": null, "full_uz": "Va odamlarga dindan qorong'i qolgan narsalarni tushuntirganida.", "note": null},
  {"num": 57, "time": "00:05:58,800 --> 00:06:04,540", "arabic": "لَا تَجِدُ مِنْهُمْ إِلَّا اعْتِرَاضًا عَلَى مُجَاهَرَاتِنَا بِالْحَقِّ", "segs": null, "full_uz": "Ulardan faqat haqiqatni oshkora aytishimizga e'tirozdan boshqa narsa topmaysan.", "note": null},
  {"num": 58, "time": "00:06:04,540 --> 00:06:07,600", "arabic": "أَلَيْسَ هَذَا بِالشَّيْءِ الْعَجِيبِ؟", "segs": null, "full_uz": "Bu ajoyib narsa emasmi?", "note": null},
  {"num": 59, "time": "00:06:08,700 --> 00:06:11,600", "arabic": "وَأَيُّ غَرَابَةٍ فِي ذَلِكَ يَا أَبَا عَبْدِ الرَّحْمَنِ؟", "segs": null, "full_uz": "Bunda qanday g'alatilik bor, Abu Abdurahmon?", "note": null},
  {"num": 60, "time": "00:06:12,400 --> 00:06:15,500", "arabic": "قَوْمٌ عَطَّلُوا الْعَقْلَ فِي أُمُورِ الدِّينِ", "segs": null, "full_uz": "Din masalalarida aqlni ishlatmay qo'ygan qavm.", "note": null},
  {"num": 61, "time": "00:06:15,500 --> 00:06:18,480", "arabic": "أَيْ يُعَطِّلُونَهُ فِي أُمُورِ الدُّنْيَا", "segs": null, "full_uz": "Ya'ni uni dunyo ishlarida ishlatishadi.", "note": null},
  {"num": 62, "time": "00:06:19,600 --> 00:06:22,900", "arabic": "لَعَلَّكَ عَلَى حَقٍّ يَا ابْنَ الْأَشْرَسِ", "segs": null, "full_uz": "Ehtimol, sen haqsan, Ibn Ashras.", "note": null},
  {"num": 63, "time": "00:06:22,900 --> 00:06:25,240", "arabic": "وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ", "segs": null, "full_uz": "Lekin odamlarning haqini kamsitmanglar.", "note": null},
  {"num": 64, "time": "00:06:25,240 --> 00:06:31,040", "arabic": "إِنَّ الَّذِينَ تَتَحَدَّثُونَ عَنْهُمْ هُمْ عُلَمَاءُ الْأُمَّةِ وَشُيُوخُهَا", "segs": null, "full_uz": "Siz gapirayotgan bu kishilar ummatning olimlari va shayxlaridir.", "note": null},
  {"num": 65, "time": "00:06:31,040 --> 00:06:34,520", "arabic": "وَهُمْ لَا يُعَطِّلُونَ عُقُولَهُمْ كَمَا تَزْعُمُونَ", "segs": null, "full_uz": "Va ular siz da'vo qilganingizdek, aqllarini ishlatmay qo'ygan emaslar.", "note": null},
  {"num": 66, "time": "00:06:34,520 --> 00:06:39,740", "arabic": "وَإِنَّمَا يُقَدِّمُونَ النَّصَّ وَالنَّقْلَ عَلَى الرَّأْيِ وَالْعَقْلِ", "segs": null, "full_uz": "Balki ular naql (rivoyat) va nassni fikr va aqldan ustun qo'yishadi.", "note": "نَقْل va نَصّ — kalom ilmida 'vahiy manbalariga asoslanish' ma'nosini beradi, 'aql'ga (mustaqil fikrga) qarama-qarshi qo'yilgan."},
  {"num": 67, "time": "00:06:39,740 --> 00:06:47,520", "arabic": "أَتَرَى فِي النَّصِّ وَالنَّقْلِ عَقْلًا يَفْهَمُ وَلِسَانًا يَشْرَحُ يَا ابْنَ أَكْثَمَ؟", "segs": [{"ar": "أَتَرَى فِي النَّصِّ وَالنَّقْلِ عَقْلًا يَفْهَمُ", "uz": "Naql va nassda tushunuvchi aql borligini ko'rasanmi"}, {"ar": "وَلِسَانًا يَشْرَحُ يَا ابْنَ أَكْثَمَ؟", "uz": "va tushuntiruvchi til borligini, Ibn Aksam?"}], "full_uz": "Naql va nassda tushunuvchi aql va tushuntiruvchi til borligini ko'rasanmi, Ibn Aksam?", "note": null},
  {"num": 68, "time": "00:06:47,519 --> 00:06:59,959", "arabic": "إِنَّا لَمْ نَضَعْ عَلَى الْكَلَامِ شَرْطًا", "segs": null, "full_uz": "Biz so'zga hech qanday shart qo'ymadik.", "note": null},
  {"num": 69, "time": "00:06:59,959 --> 00:07:02,939", "arabic": "وَلَا عَلَى اللِّسَانِ قَيْدًا", "segs": null, "full_uz": "Va tilga hech qanday bog' (cheklov) ham.", "note": null},
  {"num": 70, "time": "00:07:02,939 --> 00:07:07,060", "arabic": "فَمَنْ نَطَقَ بِالْحَقِّ حَمِدْنَاهُ", "segs": null, "full_uz": "Kim haqni aytsa, uni maqtaymiz.", "note": null},
  {"num": 71, "time": "00:07:07,060 --> 00:07:10,859", "arabic": "وَمَنْ جَهِلَ ذَلِكَ أَوْقَفْنَاهُ", "segs": null, "full_uz": "Kim buni bilmasa, uni to'xtatamiz.", "note": null},
  {"num": 72, "time": "00:07:10,859 --> 00:07:13,459", "arabic": "وَمَنْ جَهِلَ الْأَمْرَيْنِ مَعًا", "segs": null, "full_uz": "Kim ikkalasini ham bilmasa.", "note": null},
  {"num": 73, "time": "00:07:13,459 --> 00:07:15,899", "arabic": "حَكَمْنَا فِيهِ بِمَا يَجِبُ", "segs": null, "full_uz": "Unga zarur bo'lgan hukmni chiqaramiz.", "note": null},
  {"num": 74, "time": "00:07:17,519 --> 00:07:19,500", "arabic": "لَقَدْ طَفَحَ الْكَيْلُ يَا أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Sabr kosam to'ldi, Abul Abbos.", "note": "'طَفَحَ الكَيْل' — so'zma-so'z 'o'lchov idishi to'lib toshdi', ya'ni 'sabr chekkasiga yetdi' ma'nosidagi arab iborasi."},
  {"num": 75, "time": "00:07:19,500 --> 00:07:24,759", "arabic": "لَمْ أَعُدْ أَحْتَمِلُ تَسَلُّطَ هَؤُلَاءِ الْعُلُوجِ عَلَى دَوَاوِينِ الْخِلَافَةِ أَكْثَرَ مِنْ ذَلِكَ", "segs": [{"ar": "لَمْ أَعُدْ أَحْتَمِلُ تَسَلُّطَ هَؤُلَاءِ الْعُلُوجِ", "uz": "bu johillarning hukmronligiga endi chidolmayman"}, {"ar": "عَلَى دَوَاوِينِ الْخِلَافَةِ أَكْثَرَ مِنْ ذَلِكَ", "uz": "xalifalik devonlari ustidan, bundan ortiq"}], "full_uz": "Bu johillarning xalifalik devonlari ustidagi hukmronligiga endi bundan ortiq chidolmayman.", "note": null},
  {"num": 76, "time": "00:07:24,759 --> 00:07:26,959", "arabic": "لَا يَا أَبَا الْجَحْجَاحِ", "segs": null, "full_uz": "Yo'q, Abul Jahjoh.", "note": null},
  {"num": 77, "time": "00:07:26,959 --> 00:07:30,439", "arabic": "لَيْسَ هَكَذَا تُسَاسُ الْأُمُورُ يَا شَفِيعُ", "segs": null, "full_uz": "Ishlar bunday boshqarilmaydi, Shafi'.", "note": null},
  {"num": 78, "time": "00:07:30,439 --> 00:07:35,579", "arabic": "أَيُّ عَمَلٍ يَنْتَظِرُكَ إِنْ تَرَكْتَ خِدْمَةَ أَمِيرِ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Mo'minlar amiriga xizmatni tashlab qo'ysang, seni qanday ish kutadi?", "note": null},
  {"num": 79, "time": "00:07:35,579 --> 00:07:36,479", "arabic": "أَنْ أَبْقَى بِلَا عَمَلٍ", "segs": null, "full_uz": "Ishsiz qolish.", "note": null},
  {"num": 80, "time": "00:07:36,479 --> 00:07:40,939", "arabic": "خَيْرٌ لِي مِنْ عَمَلٍ يَقْطِفُ ثِمَارَهُ سِوَايَ مِمَّنْ لَا يَسْتَحِقُّونَ", "segs": [{"ar": "خَيْرٌ لِي مِنْ عَمَلٍ يَقْطِفُ ثِمَارَهُ سِوَايَ", "uz": "Bu men uchun mevasini o'zim emas boshqa biri terib oladigan ishdan yaxshiroqdir"}, {"ar": "مِمَّنْ لَا يَسْتَحِقُّونَ", "uz": "munosib bo'lmaganlardan"}], "full_uz": "Bu men uchun mevasini o'zim emas, munosib bo'lmagan boshqalar terib olayotgan ishdan yaxshiroqdir.", "note": null},
  {"num": 81, "time": "00:07:40,939 --> 00:07:44,519", "arabic": "أَلَا تَرَى كَيْفَ يَتَدَخَّلُونَ فِي كُلِّ صَغِيرَةٍ وَكَبِيرَةٍ", "segs": null, "full_uz": "Ular har bir mayda-chuyda va katta ishga qanday aralashayotganini ko'rmayapsanmi?", "note": null},
  {"num": 82, "time": "00:07:44,519 --> 00:07:49,799", "arabic": "وَيُوَلُّونَ الْمَنَاصِبَ الرَّفِيعَةَ فِي الدَّوْلَةِ لِأَبْنَاءِ جِلْدَتِهِمْ دَمًا وَنَسَبًا", "segs": null, "full_uz": "Va davlatdagi yuqori lavozimlarni qon-qarindoshligi bo'yicha o'z jinsidoshlariga topshirishmoqda.", "note": null},
  {"num": 83, "time": "00:07:49,799 --> 00:07:50,979", "arabic": "أَوْ لِمَنْ عَلَى مَذْهَبِهِمْ", "segs": null, "full_uz": "Yoki o'z mazhabidagilarga.", "note": null},
  {"num": 84, "time": "00:07:50,979 --> 00:07:56,799", "arabic": "وَمَاذَا أَقُولُ أَنَا إِذَنْ؟", "segs": null, "full_uz": "Unda men nima deyishim mumkin?", "note": null},
  {"num": 85, "time": "00:07:58,459 --> 00:08:01,240", "arabic": "هَا أَنَا ذَا جَالِسٌ فِي دَارِ ذِلَّةٍ وَامْتِهَانٍ", "segs": null, "full_uz": "Mana men xorlik va kamsitilish uyida o'tiribman.", "note": null},
  {"num": 86, "time": "00:08:01,240 --> 00:08:05,799", "arabic": "وَلَوْلَا أَنَّ الْمَأْمُونَ شَمَلَنِي بِعَفْوِهِ", "segs": null, "full_uz": "Agar Ma'mun meni o'z avfi bilan qamrab olmaganida.", "note": null},
  {"num": 87, "time": "00:08:06,579 --> 00:08:09,759", "arabic": "لَكُنْتُ قَابِعًا خَلْفَ جُدْرَانِ السُّجُونِ", "segs": null, "full_uz": "Zindonlar devori ortida o'tirgan bo'lardim.", "note": null},
  {"num": 88, "time": "00:08:09,759 --> 00:08:15,099", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Kuch-quvvat faqat Alloh bilandir.", "note": null},
  {"num": 89, "time": "00:08:15,099 --> 00:08:19,159", "arabic": "مَنْ كَانَ يَظُنُّ أَنَّ الْأُمُورَ سَتَصِلُ بِنَا إِلَى هَذَا الْحَدِّ؟", "segs": [{"ar": "مَنْ كَانَ يَظُنُّ", "uz": "Kim o'ylabdi"}, {"ar": "أَنَّ الْأُمُورَ سَتَصِلُ بِنَا إِلَى هَذَا الْحَدِّ؟", "uz": "ishlar bizni shu darajaga olib kelishini?"}], "full_uz": "Ishlar bizni shu darajaga olib kelishini kim o'ylabdi?", "note": null},
  {"num": 90, "time": "00:08:21,800 --> 00:08:23,159", "arabic": "اَلْأَيَّامُ دُوَلٌ بَيْنَ النَّاسِ", "segs": null, "full_uz": "Kunlar odamlar orasida navbatma-navbat aylanadi.", "note": "'الأيام دُوَل' — mashhur arab hikmati: baxt-omad har doim bir kishida turmaydi, u odamlar orasida almashinib turadi."},
  {"num": 91, "time": "00:08:23,759 --> 00:08:28,159", "arabic": "يَوْمٌ لَكَ وَيَوْمٌ عَلَيْكَ", "segs": null, "full_uz": "Bir kun sen uchun, bir kun senga qarshi.", "note": null},
  {"num": 92, "time": "00:08:28,159 --> 00:08:32,159", "arabic": "رَحِمَ اللَّهُ الرَّشِيدَ وَابْنَهُ الْأَمِينَ", "segs": null, "full_uz": "Alloh Rashidga va uning o'g'li Aminga rahm qilsin.", "note": null},
  {"num": 93, "time": "00:08:34,159 --> 00:08:36,580", "arabic": "رَحِمَ اللَّهُ تِلْكَ الْأَيَّامَ", "segs": null, "full_uz": "Alloh o'sha kunlarga rahm qilsin.", "note": null},
  {"num": 94, "time": "00:08:36,580 --> 00:08:42,500", "arabic": "تَوَلَّتْ وَتَوَلَّى مَعَهَا الْعِزُّ وَالْكَرَمُ", "segs": null, "full_uz": "O'tib ketdi, u bilan birga izzat va saxovat ham o'tib ketdi.", "note": null},
  {"num": 95, "time": "00:08:42,500 --> 00:08:47,620", "arabic": "مَا عَلَيْنَا إِلَّا الصَّبْرُ يَا أَبَا الْجَحْجَاحِ", "segs": null, "full_uz": "Bizga faqat sabr qilish qoladi, Abul Jahjoh.", "note": null},
  {"num": 96, "time": "00:08:47,620 --> 00:08:51,780", "arabic": "فَلَعَلَّ اللَّهَ يَمُنُّ عَلَيْنَا بِالْخَلَاصِ", "segs": null, "full_uz": "Balki Alloh bizga qutulish ne'matini beradi.", "note": null},
  {"num": 97, "time": "00:08:51,780 --> 00:08:54,820", "arabic": "أَسْأَلُ اللَّهَ ذَلِكَ", "segs": null, "full_uz": "Allohdan shuni so'rayman.", "note": null},
  {"num": 98, "time": "00:08:54,820 --> 00:08:58,920", "arabic": "وَأَرْجُو مِنْهُ أَنْ لَا يُخَيِّبَ ظَنِّي", "segs": null, "full_uz": "Va undan gumonimni oqlashini umid qilaman.", "note": null},
  {"num": 99, "time": "00:08:58,920 --> 00:09:02,379", "arabic": "فَأَنَا أَرَى الْأُمُورَ مِنْ سَيِّئٍ إِلَى أَسْوَأَ", "segs": null, "full_uz": "Chunki men ishlarning yomondan battarga tomon ketayotganini ko'ryapman.", "note": null},
  {"num": 100, "time": "00:09:36,580 --> 00:09:41,879", "arabic": "لَا سِيَّمَا أَنَّ أَخَاكَ الْإِيَادِيَّ يَدِينُ بِمَا دَانَ بِهِ أَمِيرُ الْمُؤْمِنِينَ", "segs": [{"ar": "لَا سِيَّمَا أَنَّ أَخَاكَ الْإِيَادِيَّ", "uz": "Ayniqsa, birodaringiz Iyodiy ham"}, {"ar": "يَدِينُ بِمَا دَانَ بِهِ أَمِيرُ الْمُؤْمِنِينَ", "uz": "mo'minlar amiri e'tiqod qilgan narsaga e'tiqod qiladi"}], "full_uz": "Ayniqsa, birodaringiz Iyodiy ham mo'minlar amiri e'tiqod qilgan narsaga e'tiqod qiladi.", "note": null},
  {"num": 101, "time": "00:09:41,879 --> 00:09:45,280", "arabic": "مَا أَرَاكُمْ إِلَّا مَلَأْتُمْ بَلَاطَ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Sizlar mo'minlar amiri saroyini to'ldirib tashlaganga o'xshaysizlar.", "note": null},
  {"num": 102, "time": "00:09:45,280 --> 00:09:47,800", "arabic": "وَاسْتَأْثَرْتُمْ بِهِ دُونَ النَّاسِ جَمِيعًا", "segs": null, "full_uz": "Va uni boshqa barcha odamlardan o'zingizga xos qilib olgansizlar.", "note": null},
  {"num": 103, "time": "00:09:47,800 --> 00:09:50,180", "arabic": "فَإِنْ كَانَ ذَلِكَ حَادِثًا بِي أَوْ دُونِي", "segs": null, "full_uz": "Bu men bilan sodir bo'ladimi yo mensiz.", "note": null},
  {"num": 104, "time": "00:09:50,180 --> 00:09:54,400", "arabic": "فَسَيْفٌ مَعَكَ لَا يُعْجِبُكَ خَيْرٌ مِنْ سَيْفٍ عَلَيْكَ", "segs": null, "full_uz": "Senga yoqmagan bo'lsa ham, sen bilan bo'lgan qilich, senga qarshi qilichdan yaxshiroqdir.", "note": null},
  {"num": 105, "time": "00:09:54,400 --> 00:09:57,800", "arabic": "أَنَا وَعَدْتُكَ وَسَأَفِي لَكَ بِوَعْدِي", "segs": null, "full_uz": "Men senga va'da berdim va va'damni bajaraman.", "note": null},
  {"num": 106, "time": "00:09:57,800 --> 00:10:01,340", "arabic": "وَلَنْ تَجِدَ نَفْسَكَ إِلَّا مَاثِلًا أَمَامَ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Va o'zingni mo'minlar amiri huzurida turgan holda topasan.", "note": null},
  {"num": 107, "time": "00:10:01,340 --> 00:10:04,040", "arabic": "أَنَا أَعْرِفُ أَنَّكَ سَتَنَالُ إِعْجَابًا", "segs": null, "full_uz": "Bilaman, sen uning e'tiborini qozonasan.", "note": null},
  {"num": 108, "time": "00:10:04,039 --> 00:10:09,240", "arabic": "وَخَاصَّةً أَنَّكَ رَجُلٌ مُفَوَّهٌ ذَكِيُّ الْقَلْبِ لَا تَنْقُصُكَ الْفِطْنَةُ", "segs": null, "full_uz": "Ayniqsa, sen mulozamatli, aqlli va zukko odamsan.", "note": null},
  {"num": 109, "time": "00:10:09,240 --> 00:10:12,639", "arabic": "شُكْرًا لَكَ عَلَى ثِقَتِكَ بِي يَا ابْنَ أَكْثَمَ", "segs": null, "full_uz": "Menga ishonganingiz uchun rahmat, Ibn Aksam.", "note": null},
  {"num": 110, "time": "00:10:12,639 --> 00:10:16,120", "arabic": "وَلَنْ أَنْسَى لَكَ ذَلِكَ مُحِيطٌ", "segs": null, "full_uz": "Va buni sizga hech qachon unutmayman.", "note": null},
  {"num": 111, "time": "00:11:34,039 --> 00:11:46,939", "arabic": "وَعَنِ الْحَسَنِ بْنِ زَيْدِ بْنِ حَسَنٍ قَالَ", "segs": null, "full_uz": "Hasan ibn Zayd ibn Hasan rivoyat qildi.", "note": null},
  {"num": 112, "time": "00:11:46,939 --> 00:11:52,419", "arabic": "حَدَّثَنِي أَبِي عَنْ أَبِيهِ عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ", "segs": [{"ar": "حَدَّثَنِي أَبِي عَنْ أَبِيهِ", "uz": "Otam menga o'z otasidan rivoyat qildi"}, {"ar": "عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ", "uz": "u esa Ali ibn Abu Tolib roziyallohu anhudan, u aytdi"}], "full_uz": "Otam menga o'z otasidan, u esa Ali ibn Abu Tolib roziyallohu anhudan rivoyat qildi, u aytdi.", "note": null},
  {"num": 113, "time": "00:11:52,419 --> 00:11:56,159", "arabic": "كُنْتُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Men Payg'ambar sollallohu alayhi va sallam huzurida edim.", "note": null},
  {"num": 114, "time": "00:11:58,480 --> 00:12:02,459", "arabic": "فَأَقْبَلَ أَبُو بَكْرٍ وَعُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُمَا", "segs": null, "full_uz": "Shunda Abu Bakr va Umar ibn Xattob roziyallohu anhumo kelib qolishdi.", "note": null},
  {"num": 115, "time": "00:12:02,460 --> 00:12:08,320", "arabic": "فَقَالَ يَا عَلِيُّ هَذَانِ سَيِّدَاكَ لِأَهْلِ الْجَنَّةِ وَشَبَابِهَا", "segs": null, "full_uz": "U aytdi: 'Ey Ali, bu ikkovi jannat ahlining va uning yigitlarining sayyidlaridir.'", "note": null},
  {"num": 116, "time": "00:12:08,320 --> 00:12:10,800", "arabic": "بَعْدَ النَّبِيِّينَ وَالْمُرْسَلِينَ", "segs": null, "full_uz": "Payg'ambarlar va rasullardan keyin.", "note": null},
  {"num": 117, "time": "00:12:10,800 --> 00:12:17,100", "arabic": "لَوْ تَدْرِي كَمْ أَنَا سَعِيدٌ بِرُؤْيَتِكَ مَرَّةً أُخْرَى يَا أُسَامَةُ", "segs": [{"ar": "لَوْ تَدْرِي كَمْ أَنَا سَعِيدٌ بِرُؤْيَتِكَ مَرَّةً أُخْرَى", "uz": "Bilsang edi, seni yana ko'rganimdan qanchalik xursandman"}, {"ar": "يَا أُسَامَةُ", "uz": "Usoma"}], "full_uz": "Bilsang edi, seni yana ko'rganimdan qanchalik xursandman, Usoma.", "note": null},
  {"num": 118, "time": "00:12:17,100 --> 00:12:20,980", "arabic": "قَدْ حَسِبْتُ بَعْدَ اخْتِفَائِكَ أَنَّكَ فِي سِجْنِ هَارُونَ", "segs": null, "full_uz": "Yashiringaningdan keyin, Horunning zindonida deb o'ylagandim.", "note": null},
  {"num": 119, "time": "00:12:20,980 --> 00:12:25,060", "arabic": "أَوْ بَيْنَ الشُّهَدَاءِ مِنْ إِخْوَتِنَا عَلَى يَدَيْ هَذَا الظَّالِمِ", "segs": null, "full_uz": "Yoki shu zolimning qo'lidan shahid bo'lgan birodarlarimiz orasida deb.", "note": null},
  {"num": 120, "time": "00:12:25,060 --> 00:12:31,019", "arabic": "كَانَ لَوْ حَدَثَ ذَلِكَ أَسْهَلَ بِكَثِيرٍ مِمَّا جَرَى لِي يَا أَبَا عَبْدِ الرَّحْمَنِ", "segs": [{"ar": "كَانَ لَوْ حَدَثَ ذَلِكَ أَسْهَلَ بِكَثِيرٍ مِمَّا جَرَى لِي", "uz": "Agar shunday bo'lganida, menga bo'lganidan ko'ra ancha osonroq bo'lardi"}, {"ar": "يَا أَبَا عَبْدِ الرَّحْمَنِ", "uz": "Abu Abdurahmon"}], "full_uz": "Agar shunday bo'lganida, menga bo'lganidan ko'ra ancha osonroq bo'lardi, Abu Abdurahmon.", "note": null},
  {"num": 121, "time": "00:12:36,220 --> 00:12:39,519", "arabic": "لَقَدْ قَضَيْتُ السِّنِينَ الْمَاضِيَةَ مُشَرَّدًا فِي الْبِلَادِ", "segs": null, "full_uz": "O'tgan yillarni yurtlarda darbadar bo'lib o'tkazdim.", "note": null},
  {"num": 122, "time": "00:12:39,519 --> 00:12:41,259", "arabic": "بَعْدَ أَنْ أَلْقَى جُنْدُ هَارُونَ الْقَبْضَ عَلَى إِخْوَتِنَا", "segs": null, "full_uz": "Horunning askarlari birodarlarimizni hibsga olgandan keyin.", "note": null},
  {"num": 123, "time": "00:12:41,259 --> 00:12:44,519", "arabic": "وَحَاوَلُوا الْقَبْضَ عَلَيَّ", "segs": null, "full_uz": "Va meni ham hibsga olishga urinishdi.", "note": null},
  {"num": 124, "time": "00:12:44,519 --> 00:12:48,120", "arabic": "اَلْحَمْدُ لِلَّهِ خَلَّصَكَ اللَّهُ مِنْ بَرَاثِنِهِمْ", "segs": null, "full_uz": "Allohga hamdlar bo'lsin, Alloh seni ularning changalidan qutqargan.", "note": null},
  {"num": 125, "time": "00:12:48,120 --> 00:12:51,319", "arabic": "وَإِنْ كُنْتُ طِيلَةَ هَذِهِ الْفَتْرَةِ", "segs": null, "full_uz": "Garchi bu davr mobaynida.", "note": null},
  {"num": 126, "time": "00:12:51,319 --> 00:12:54,079", "arabic": "فِي أَرْضِ اللَّهِ الْوَاسِعَةِ", "segs": null, "full_uz": "Allohning keng yerida (bo'lsam ham).", "note": null},
  {"num": 127, "time": "00:12:54,079 --> 00:12:56,579", "arabic": "أَلَمْ يَقُلْ سُبْحَانَهُ وَتَعَالَى", "segs": null, "full_uz": "Subhonahu va taolo aytmaganmidi.", "note": null},
  {"num": 128, "time": "00:12:56,579 --> 00:12:59,740", "arabic": "يَا عِبَادِيَ الَّذِينَ آمَنُوا", "segs": null, "full_uz": "'Ey iymon keltirgan bandalarim.'", "note": null},
  {"num": 129, "time": "00:12:59,740 --> 00:13:03,700", "arabic": "إِنَّ أَرْضِي وَاسِعَةٌ فَإِيَّايَ فَاعْبُدُونِ", "segs": null, "full_uz": "'Albatta Mening yerim kengdir, faqat Menga ibodat qilinglar.'", "note": "'Ankabut' surasi, 56-oyat — zulm makonini tark etib, boshqa joyda dinni erkin tutish mumkinligi haqidagi oyat."},
  {"num": 130, "time": "00:13:03,700 --> 00:13:08,120", "arabic": "لَقَدْ خَرَجْتُ مِنْ هَذَا الْبَلَدِ الظَّالِمِ أَهْلُهُ", "segs": null, "full_uz": "Men ahli zolim bo'lgan bu yurtdan chiqib ketdim.", "note": null},
  {"num": 131, "time": "00:13:08,120 --> 00:13:12,460", "arabic": "فَمَا الَّذِي مَنَعَكَ مِنَ الْعَوْدَةِ إِلَى بَغْدَادَ بَعْدَ أَنْ قُتِلَ الْأَمِينُ", "segs": [{"ar": "فَمَا الَّذِي مَنَعَكَ مِنَ الْعَوْدَةِ إِلَى بَغْدَادَ", "uz": "Bag'dodga qaytishingga nima to'sqinlik qildi"}, {"ar": "بَعْدَ أَنْ قُتِلَ الْأَمِينُ", "uz": "Amin o'ldirilgandan keyin"}], "full_uz": "Amin o'ldirilgandan keyin Bag'dodga qaytishingga nima to'sqinlik qildi?", "note": null},
  {"num": 132, "time": "00:13:12,460 --> 00:13:18,039", "arabic": "وَاسْتَتَبَّ الْأَمْرُ لِأَمِيرِ الْمُؤْمِنِينَ الْمَأْمُونِ حَفِظَهُ اللَّهُ", "segs": null, "full_uz": "Va hokimiyat mo'minlar amiri Ma'mun qo'lida (Alloh uni asrasin) barqarorlashgan edi.", "note": null},
  {"num": 133, "time": "00:13:18,039 --> 00:13:25,100", "arabic": "اَلْحَقُّ يَا شَيْخِي أَنِّي حَسِبْتُ أَنَّ الْمَأْمُونَ سَيَسِيرُ عَلَى خُطَى أَبِيهِ وَأَخِيهِ", "segs": [{"ar": "اَلْحَقُّ يَا شَيْخِي أَنِّي حَسِبْتُ", "uz": "Rostini aytsam, ustozim, men o'ylagandim"}, {"ar": "أَنَّ الْمَأْمُونَ سَيَسِيرُ عَلَى خُطَى أَبِيهِ وَأَخِيهِ", "uz": "Ma'mun ham otasi va akasining izidan boradi, deb"}], "full_uz": "Rostini aytsam, ustozim, men Ma'mun ham otasi va akasining izidan boradi, deb o'ylagandim.", "note": null},
  {"num": 134, "time": "00:13:25,100 --> 00:13:27,480", "arabic": "وَلَقَدْ زَادَ الظُّنُونَ عِنْدَمَا سَمِعْتُ أَنَّهُ لَزِمَ مَرْوَ فِي خُرَاسَانَ وَلَمْ يَقْدُمْ إِلَيْهَا", "segs": [{"ar": "وَلَقَدْ زَادَ الظُّنُونَ", "uz": "gumonlarim yanada kuchaygan edi"}, {"ar": "عِنْدَمَا سَمِعْتُ أَنَّهُ لَزِمَ مَرْوَ فِي خُرَاسَانَ وَلَمْ يَقْدُمْ إِلَيْهَا", "uz": "uning Xuroson Marvida qolib, Bag'dodga kelmaganini eshitganimda"}], "full_uz": "Uning Xuroson Marvida qolib, Bag'dodga kelmaganini eshitganimda gumonlarim yanada kuchaygan edi.", "note": null},
  {"num": 135, "time": "00:13:27,480 --> 00:13:30,379", "arabic": "غَفَرَ اللَّهُ لَكَ يَا أُسَامَةُ", "segs": null, "full_uz": "Alloh seni mag'firat qilsin, Usoma.", "note": null},
  {"num": 136, "time": "00:13:30,379 --> 00:13:33,740", "arabic": "أَلَمْ تَكُنْ تَدْرِي أَنَّ أَمِيرَ الْمُؤْمِنِينَ الْمَأْمُونَ", "segs": null, "full_uz": "Mo'minlar amiri Ma'mun bilmasmiding.", "note": null},
  {"num": 137, "time": "00:13:33,740 --> 00:13:35,379", "arabic": "رَجُلٌ لَا يَنْخَدِعُ بِفَتَاوَى الْفُقَهَاءِ", "segs": null, "full_uz": "U fuqahoning fatvolariga aldanmaydigan odam.", "note": null},
  {"num": 138, "time": "00:13:35,379 --> 00:13:37,159", "arabic": "وَلَا هَذَيَانِ أَهْلِ الْحَدِيثِ", "segs": null, "full_uz": "Va ahli hadisning bo'sh gaplariga ham.", "note": null},
  {"num": 139, "time": "00:13:37,159 --> 00:13:39,779", "arabic": "اَلْحَقُّ أَنِّي لَمْ أَعْرِفْ ذَلِكَ", "segs": null, "full_uz": "Rostini aytsam, buni bilmagan edim.", "note": null},
  {"num": 140, "time": "00:13:39,779 --> 00:13:42,600", "arabic": "إِلَّا بَعْدَ عَوْدَتِي هَذِهِ السَّنَةَ إِلَى بَغْدَادَ", "segs": null, "full_uz": "Faqat shu yili Bag'dodga qaytganimdan keyingina.", "note": null},
  {"num": 141, "time": "00:13:42,600 --> 00:13:45,980", "arabic": "وَسَمَاحِي لِإِخْوَتِنَا بِالْجَهْرِ بِعَقِيدَتِنَا", "segs": null, "full_uz": "Va birodarlarimizga aqidamizni oshkora aytishga ruxsat berilganidan keyin.", "note": null},
  {"num": 142, "time": "00:13:45,980 --> 00:13:48,759", "arabic": "فَأَرْسَلَ إِلَيَّ أَحَدُ الْإِخْوَةِ أَنِ اقْدَمْ بَغْدَادَ", "segs": null, "full_uz": "Birodarlardan biri menga 'Bag'dodga kel' deb xabar yuborgan edi.", "note": null},
  {"num": 143, "time": "00:13:48,759 --> 00:13:52,420", "arabic": "فَإِنَّ الْأُمُورَ فِيهَا عَلَى مَا نُحِبُّ", "segs": null, "full_uz": "Chunki u yerdagi ishlar biz istagandek ekan.", "note": null},
  {"num": 144, "time": "00:13:52,420 --> 00:13:54,180", "arabic": "وَالْحَمْدُ لِلَّهِ أَنَّنِي رَأَيْتُهَا كَمَا نَشْتَهِي", "segs": null, "full_uz": "Va Allohga hamdlar bo'lsin, uni biz xohlagandek ko'rdim.", "note": null},
  {"num": 145, "time": "00:13:54,179 --> 00:13:55,859", "arabic": "وَأَوَّلُ شَيْءٍ فَعَلْتُهُ", "segs": null, "full_uz": "Va qilgan birinchi ishim.", "note": null},
  {"num": 146, "time": "00:13:55,859 --> 00:13:56,919", "arabic": "اَلْبَحْثُ عَنْكَ", "segs": null, "full_uz": "Seni qidirish edi.", "note": null},
  {"num": 147, "time": "00:13:56,919 --> 00:14:00,139", "arabic": "اَلْحَمْدُ لِلَّهِ أَنْ جَمَعَنَا مَرَّةً أُخْرَى يَا أُسَامَةُ", "segs": null, "full_uz": "Bizni yana bir marta jamlagan Allohga hamdlar bo'lsin, Usoma.", "note": null},
  {"num": 148, "time": "00:14:00,139 --> 00:14:03,479", "arabic": "بَغْدَادُ لَمْ تَعُدْ بَلَدًا ظَالِمًا أَهْلُهُ", "segs": null, "full_uz": "Bag'dod endi ahli zolim bo'lgan yurt emas.", "note": null},
  {"num": 149, "time": "00:14:03,479 --> 00:14:06,639", "arabic": "بَغْدَادُ عَادَتْ إِلَيْهَا أَنْوَارُ الْيَقِينِ", "segs": null, "full_uz": "Bag'dodga yaqin nurlari qaytib keldi.", "note": null},
  {"num": 150, "time": "00:14:06,639 --> 00:14:09,639", "arabic": "وَهَا هُمْ إِخْوَتُكَ يَصْدَحُونَ فِي جَنَبَاتِهَا", "segs": null, "full_uz": "Va mana, birodarlaring uning har burchagida ochiq gapirmoqda.", "note": null},
  {"num": 151, "time": "00:14:09,639 --> 00:14:12,959", "arabic": "دُونَ أَنْ يَجْرُؤَ أَحَدٌ عَلَى التَّعَرُّضِ لَهُمْ", "segs": null, "full_uz": "Hech kim ularga tegishga jur'at etolmaydi.", "note": null},
  {"num": 152, "time": "00:14:12,959 --> 00:14:15,819", "arabic": "اَلْحَمْدُ لِلَّهِ الَّذِي مَنَّ عَلَيْنَا بِذَلِكَ", "segs": null, "full_uz": "Bizga shuni in'om etgan Allohga hamdlar bo'lsin.", "note": null},
  {"num": 153, "time": "00:14:15,819 --> 00:14:17,359", "arabic": "اَلْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Allohga hamdlar bo'lsin.", "note": null},
  {"num": 154, "time": "00:14:17,359 --> 00:14:18,519", "arabic": "اَلْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Allohga hamdlar bo'lsin.", "note": null},
  {"num": 155, "time": "00:14:18,519 --> 00:14:24,579", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Assalomu alaykum va rahmatulloh.", "note": null},
  {"num": 156, "time": "00:14:24,579 --> 00:14:26,279", "arabic": "أَيْنَ كُنْتَ يَا مُحَمَّدُ؟", "segs": null, "full_uz": "Qayerda eding, Muhammad?", "note": null},
  {"num": 157, "time": "00:14:26,279 --> 00:14:27,579", "arabic": "كَانَ هُنَاكَ مَا يَشْغَلُنِي", "segs": null, "full_uz": "Meni band qilgan bir ish bor edi.", "note": null},
  {"num": 158, "time": "00:14:27,579 --> 00:14:30,419", "arabic": "هَيَّا بِنَا", "segs": null, "full_uz": "Yuring, ketdik.", "note": null},
  {"num": 159, "time": "00:14:30,419 --> 00:14:34,220", "arabic": "كُلُّ الْأَدِلَّةِ تَقْطَعُ بِأَنَّ الْقُرْآنَ مَخْلُوقٌ", "segs": null, "full_uz": "Barcha dalillar Qur'on yaratilgan, deb qat'iy hukm chiqaradi.", "note": null},
  {"num": 160, "time": "00:14:34,220 --> 00:14:40,519", "arabic": "وَكُلُّ الْأَدِلَّةِ تَقْطَعُ بِاسْتِحَالَةِ رُؤْيَةِ اللَّهِ يَوْمَ الْقِيَامَةِ", "segs": null, "full_uz": "Va barcha dalillar Qiyomat kunida Allohni ko'rish mumkin emasligini qat'iy isbotlaydi.", "note": null},
  {"num": 161, "time": "00:14:40,519 --> 00:14:43,259", "arabic": "وَمَنْ يَقُولُ غَيْرَ ذَلِكَ فَهُوَ كَافِرٌ", "segs": null, "full_uz": "Kim boshqacha desa, u kofirdir.", "note": null},
  {"num": 162, "time": "00:14:43,259 --> 00:14:45,779", "arabic": "كَافِرٌ كُفْرَ اعْتِقَادٍ", "segs": null, "full_uz": "E'tiqod kufri bilan kofirdir.", "note": null},
  {"num": 163, "time": "00:14:45,779 --> 00:14:48,460", "arabic": "أَسَمِعْتَ يَا أَبَا عَبْدِ اللَّهِ؟", "segs": null, "full_uz": "Eshitdingmi, Abu Abdulloh?", "note": null},
  {"num": 164, "time": "00:14:48,460 --> 00:14:51,040", "arabic": "كَبُرَتْ كَلِمَةً تَخْرُجُ مِنْ أَفْوَاهِهِمْ", "segs": null, "full_uz": "Og'izlaridan chiqqan qanchalik og'ir bir so'z!", "note": null},
  {"num": 165, "time": "00:14:51,040 --> 00:14:54,300", "arabic": "هَؤُلَاءِ قَوْمٌ يَقُولُونَ عَلَى اللَّهِ مَا لَا يَعْلَمُونَ", "segs": null, "full_uz": "Bular Alloh haqida bilmagan narsalarini aytadigan qavmdir.", "note": null},
  {"num": 166, "time": "00:14:54,300 --> 00:14:58,120", "arabic": "إِنْ كَانَ الْمَأْمُونُ يَدِينُ بِمَا نَدِينُ بِهِ", "segs": null, "full_uz": "Agar Ma'mun ham biz e'tiqod qilgan narsaga e'tiqod qilsa.", "note": null},
  {"num": 167, "time": "00:14:58,120 --> 00:15:02,019", "arabic": "فَيَجْدُرُ بِهِ أَنْ يَمْنَعَ عُلَمَاءَ الْعَوَامِّ", "segs": null, "full_uz": "Unga omma olimlarini man qilish yarashadi.", "note": null},
  {"num": 168, "time": "00:15:02,019 --> 00:15:06,460", "arabic": "اَلَّذِينَ يُسَمُّونَ أَنْفُسَهُمْ ظُلْمًا بِأَهْلِ السُّنَّةِ وَالْجَمَاعَةِ", "segs": null, "full_uz": "O'zlarini nohaq ravishda 'ahli sunna val jamoa' deb ataydiganlarni.", "note": null},
  {"num": 169, "time": "00:15:07,500 --> 00:15:09,320", "arabic": "أَنْ يَمْنَعَهُمْ مِنْ إِفْسَادِ الْعُقُولِ", "segs": null, "full_uz": "Ularni aqllarni buzishdan to'xtatishi kerak.", "note": null},
  {"num": 170, "time": "00:15:09,320 --> 00:15:11,580", "arabic": "يَجِبُ أَنْ يُحَاصِرَهُمْ", "segs": null, "full_uz": "Ularni qamal qilishi shart.", "note": null},
  {"num": 171, "time": "00:15:11,580 --> 00:15:15,100", "arabic": "وَيَمْنَعَهُمْ مِنْ بَثِّ السُّمُومِ بَيْنَ النَّاسِ", "segs": null, "full_uz": "Va ularni odamlar orasida zahar sochishdan to'xtatishi kerak.", "note": null},
  {"num": 172, "time": "00:15:15,100 --> 00:15:19,100", "arabic": "أَنْتَ تَتَعَجَّلُ الْأُمُورَ يَا ابْنَ أَبِي دُؤَادٍ", "segs": null, "full_uz": "Sen ishlarni shoshiltiryapsan, Ibn Abu Duod.", "note": null},
  {"num": 173, "time": "00:15:19,100 --> 00:15:22,240", "arabic": "إِنَّ الْأَمْرَ لَيْسَ بِهَذِهِ السُّهُولَةِ", "segs": null, "full_uz": "Bu ish bunchalik oson emas.", "note": null},
  {"num": 174, "time": "00:15:22,240 --> 00:15:25,659", "arabic": "وَلَا تَحْسَبْ أَنَّنِي غَافِلٌ عَنْ أَفْعَالِهِمْ", "segs": null, "full_uz": "Va ularning qilmishlaridan g'ofil, deb o'ylama.", "note": null},
  {"num": 175, "time": "00:15:25,659 --> 00:15:32,320", "arabic": "وَإِلَى أَيْنَ وَصَلْتَ يَا ثُمَامَةُ؟", "segs": null, "full_uz": "Qayergacha yetib bording, Sumoma?", "note": null},
  {"num": 176, "time": "00:15:32,320 --> 00:15:34,159", "arabic": "اَلْأَمْرُ مَا أَقُولُهُ لَكَ الْآنَ", "segs": null, "full_uz": "Ish, senga hozir aytadiganim shu.", "note": null},
  {"num": 177, "time": "00:15:34,159 --> 00:15:38,920", "arabic": "اَلْمَأْمُونُ لَا يُرِيدُ إِثَارَةَ الْعَوَامِّ عَلَيْهِ", "segs": null, "full_uz": "Ma'mun ommani o'ziga qarshi qo'zg'atishni istamaydi.", "note": null},
  {"num": 178, "time": "00:15:38,920 --> 00:15:41,779", "arabic": "فِي هَذَا الْوَقْتِ عَلَى الْأَقَلِّ", "segs": null, "full_uz": "Hech bo'lmasa hozircha.", "note": null},
  {"num": 179, "time": "00:15:41,779 --> 00:15:44,560", "arabic": "أَنْتَ تَعْرِفُ كُلَّ ذَلِكَ", "segs": null, "full_uz": "Sen buning hammasini bilasan.", "note": null},
  {"num": 180, "time": "00:15:44,559 --> 00:15:46,139", "arabic": "فَلَا دَاعِيَ لِلشَّرْحِ", "segs": null, "full_uz": "Tushuntirishga hojat yo'q.", "note": null},
  {"num": 181, "time": "00:15:46,139 --> 00:15:51,559", "arabic": "اَلْحَرْبُ تَحْتَاجُ أَحْيَانًا إِلَى هُدْنَةٍ", "segs": null, "full_uz": "Urush ba'zan sulh (bitim)ga muhtoj bo'ladi.", "note": null},
  {"num": 182, "time": "00:15:51,559 --> 00:15:55,559", "arabic": "نَادِرًا يَا ابْنَ الْأَشْرَسِ", "segs": null, "full_uz": "Kamdan-kam, Ibn Ashras.", "note": null},
  {"num": 183, "time": "00:15:55,559 --> 00:15:58,759", "arabic": "إِنَّ فِي قَلْبِي", "segs": null, "full_uz": "Qalbimda...", "note": null},
  {"num": 184, "time": "00:15:58,759 --> 00:16:00,559", "arabic": "إِنَّ فِي قَلْبِكَ غَيْظًا", "segs": null, "full_uz": "Qalbingda g'azab bor.", "note": null},
  {"num": 185, "time": "00:16:01,199 --> 00:16:06,000", "arabic": "يَجْعَلُكَ تَغْفُلُ عَنْ رُؤْيَةِ الْأُمُورِ بِشَكْلٍ صَحِيحٍ", "segs": null, "full_uz": "Bu esa seni ishlarni to'g'ri ko'rishdan g'ofil qilib qo'yadi.", "note": null},
  {"num": 186, "time": "00:16:06,000 --> 00:16:11,500", "arabic": "إِنَّ إِخْوَانَنَا الْآنَ يَتَفَشَّوْنَ فِي جَسَدِ الْأُمَّةِ", "segs": null, "full_uz": "Birodarlarimiz hozir ummat tanasiga keng yoyilmoqda.", "note": null},
  {"num": 187, "time": "00:16:11,500 --> 00:16:14,399", "arabic": "وَيُمْسِكُونَ بِجَمِيعِ مَفَاصِلِهَا", "segs": null, "full_uz": "Va uning barcha bo'g'inlarini qo'lga olmoqda.", "note": null},
  {"num": 188, "time": "00:16:14,399 --> 00:16:17,019", "arabic": "وَإِلَى أَنْ يَتِمَّ لَنَا التَّمْكِينُ", "segs": null, "full_uz": "Va bizga to'liq imkoniyat (hukmronlik) berilguncha.", "note": null},
  {"num": 189, "time": "00:16:17,019 --> 00:16:22,100", "arabic": "عِنْدَهَا فَقَطْ سَنَرُدُّ عَلَى هَؤُلَاءِ الْعَوَامِّ ظُلْمَهُمْ", "segs": null, "full_uz": "O'shanda ana shu omma zulmiga qarshi javob qaytaramiz.", "note": null},
  {"num": 190, "time": "00:16:22,100 --> 00:16:27,319", "arabic": "إِنَّ الْأَمْرَ بِحَاجَةٍ إِلَى الْكَثِيرِ مِنَ التَّأَنِّي يَا ابْنَ أَبِي دُؤَادٍ", "segs": [{"ar": "إِنَّ الْأَمْرَ بِحَاجَةٍ إِلَى الْكَثِيرِ مِنَ التَّأَنِّي", "uz": "Bu ish ko'p sabr-toqatga muhtoj"}, {"ar": "يَا ابْنَ أَبِي دُؤَادٍ", "uz": "Ibn Abu Duod"}], "full_uz": "Bu ish ko'p sabr-toqatga muhtoj, Ibn Abu Duod.", "note": null},
  {"num": 191, "time": "00:16:27,319 --> 00:16:31,959", "arabic": "وَإِلَّا خَسِرْنَا صَبْرَ كُلِّ هَذِهِ السِّنِينَ", "segs": null, "full_uz": "Aks holda, shuncha yillik sabrimizni yo'qotamiz.", "note": null},
  {"num": 192, "time": "00:16:31,959 --> 00:16:39,799", "arabic": "إِنَّمَا أَقُولُ ذَلِكَ غَيْرَةً عَلَى دِينِي وَاعْتِقَادِي كَمَا تَعْلَمُ", "segs": null, "full_uz": "Buni faqat dinim va aqidamga g'ayrat qilib aytyapman, o'zing bilasan.", "note": null},
  {"num": 193, "time": "00:16:39,799 --> 00:16:47,039", "arabic": "أَعْرِفُ وَأَعْرِفُ أَيْضًا أَنَّ أَيَّ خَطَإٍ سَنَدْفَعُ نَحْنُ ثَمَنَهُ", "segs": null, "full_uz": "Bilaman, va shuni ham bilamanki, har qanday xato bo'lsa, uning narxini biz to'laymiz.", "note": null},
  {"num": 194, "time": "00:16:47,039 --> 00:16:48,539", "arabic": "اَلصَّبْرُ", "segs": null, "full_uz": "Sabr.", "note": null},
  {"num": 195, "time": "00:16:48,539 --> 00:16:52,079", "arabic": "اَلصَّبْرُ يَا ابْنَ أَبِي دُؤَادٍ", "segs": null, "full_uz": "Sabr, Ibn Abu Duod.", "note": null},
  {"num": 196, "time": "00:16:52,080 --> 00:17:09,880", "arabic": "أَضْحَتْ بَغْدَادُ مَكَانًا لَا يُطَاقُ", "segs": null, "full_uz": "Bag'dod chidab bo'lmas joyga aylandi.", "note": null},
  {"num": 197, "time": "00:17:09,880 --> 00:17:13,259", "arabic": "صِرْنَا نَرَى الْجَهْمِيَّةَ وَالْمُعْتَزِلَةَ بَيْنَنَا فِي كُلِّ مَكَانٍ", "segs": null, "full_uz": "Endi jahmiya va mu'tazilalarni har joyda, orasimizda ko'rmoqdamiz.", "note": null},
  {"num": 198, "time": "00:17:13,259 --> 00:17:15,720", "arabic": "فِي الْمَسْجِدِ وَالسُّوقِ وَالْأَزِقَّةِ", "segs": null, "full_uz": "Masjidda, bozorda va ko'chalarda.", "note": null},
  {"num": 199, "time": "00:17:15,720 --> 00:17:18,880", "arabic": "يُوشِكُونَ أَنْ يَدْخُلُوا عَلَيْنَا بُيُوتَنَا", "segs": null, "full_uz": "Uylarimizga ham kirib kelishlariga oz qoldi.", "note": null},
  {"num": 200, "time": "00:17:18,880 --> 00:17:21,519", "arabic": "وَلَا نَجْرُؤُ عَلَى أَنْ نَمْنَعَهُمْ", "segs": null, "full_uz": "Va biz ularga to'sqinlik qilishga jur'at etolmaymiz.", "note": null},
  {"num": 201, "time": "00:17:21,519 --> 00:17:24,119", "arabic": "فَقَدْ أَحَاطَهُمُ الْمَأْمُونُ بِعِنَايَةٍ", "segs": null, "full_uz": "Chunki Ma'mun ularni o'z himoyasi bilan o'rab olgan.", "note": null},
  {"num": 202, "time": "00:17:24,119 --> 00:17:28,460", "arabic": "غَفَرَ اللَّهُ لِأَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Alloh mo'minlar amirini mag'firat qilsin.", "note": null},
  {"num": 203, "time": "00:17:28,460 --> 00:17:32,359", "arabic": "لَوْلَا أَنَّهُ سَمَحَ لَهُمْ بِنَشْرِ بِدَعِهِمْ بَيْنَنَا", "segs": null, "full_uz": "Agar u orasimizda o'z bid'atlarini tarqatishga ruxsat bermaganida.", "note": null},
  {"num": 204, "time": "00:17:32,359 --> 00:17:34,599", "arabic": "لَمَا كَانَ لَنَا أَنْ نَرَاهُمْ", "segs": null, "full_uz": "Ularni ko'rmagan ham bo'lardik.", "note": null},
  {"num": 205, "time": "00:17:34,599 --> 00:17:37,960", "arabic": "فَقَدْ كَانُوا فِي عَهْدِ الرَّشِيدِ وَالْأَمِينِ رَحِمَهُمَا اللَّهُ", "segs": null, "full_uz": "Chunki Rashid va Amin davrida — Alloh ularga rahm qilsin.", "note": null},
  {"num": 206, "time": "00:17:37,960 --> 00:17:40,379", "arabic": "لَا يَجْرُؤُونَ عَلَى إِظْهَارِ بِدَعِهِمْ", "segs": null, "full_uz": "O'z bid'atlarini oshkor qilishga jur'at etishmagan edi.", "note": null},
  {"num": 207, "time": "00:17:40,379 --> 00:17:43,160", "arabic": "فَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Kuch-quvvat faqat Alloh bilandir.", "note": null},
  {"num": 208, "time": "00:17:43,160 --> 00:17:45,639", "arabic": "أَلَا يَجْدُرُ بِنَا أَنْ نُوَجِّهَهُمْ يَا إِمَامُ؟", "segs": null, "full_uz": "Ularga to'g'ri yo'l ko'rsatishimiz kerak emasmi, imom?", "note": null},
  {"num": 209, "time": "00:17:45,639 --> 00:17:48,920", "arabic": "لَا يَا أَبَا بَكْرٍ", "segs": null, "full_uz": "Yo'q, Abu Bakr.", "note": null},
  {"num": 210, "time": "00:17:48,920 --> 00:17:53,820", "arabic": "إِنْ فَعَلْنَا فَقَدْ أَهْدَيْنَاهُمْ مَا يَنْتَظِرُونَ وَمَا يَتَرَقَّبُونَ", "segs": null, "full_uz": "Buni qilsak, ularga kutayotgan va poylayotgan narsani sovg'a qilgan bo'lamiz.", "note": null},
  {"num": 211, "time": "00:17:53,820 --> 00:17:58,019", "arabic": "وَلَكِنْ كَثْرَةٌ مِنَ الْعَوَامِّ يَسْتَمِعُونَ إِلَيْهِمْ", "segs": null, "full_uz": "Lekin ommaning ko'pchiligi ularni tinglayapti.", "note": null},
  {"num": 212, "time": "00:17:58,019 --> 00:18:00,539", "arabic": "فَهَلْ نَظَلُّ هَكَذَا مَكْتُوفِي الْأَيْدِي؟", "segs": null, "full_uz": "Unda shunday qo'l qovushtirib turaveramizmi?", "note": null},
  {"num": 213, "time": "00:18:01,960 --> 00:18:03,640", "arabic": "وَلَا ذَلِكَ يَا فُوَرَانُ", "segs": null, "full_uz": "U ham emas, Furon.", "note": null},
  {"num": 214, "time": "00:18:03,640 --> 00:18:07,039", "arabic": "يَجِبُ عَلَيْنَا أَنْ لَا نُخَالِطَهُمْ أَوْ نُجَالِسَهُمْ", "segs": null, "full_uz": "Biz ular bilan aralashmasligimiz yoki o'tirmasligimiz kerak.", "note": null},
  {"num": 215, "time": "00:18:07,039 --> 00:18:12,539", "arabic": "وَفِي الْوَقْتِ نَفْسِهِ يَجِبُ أَنْ لَا نَتْرُكَ طَرِيقًا لِتَعْلِيمِ النَّاسِ الْعَقِيدَةَ الصَّحِيحَةَ إِلَّا سَلَكْنَاهُ", "segs": [{"ar": "وَفِي الْوَقْتِ نَفْسِهِ يَجِبُ أَنْ لَا نَتْرُكَ طَرِيقًا", "uz": "shu bilan birga, hech qanday yo'lni qoldirmasligimiz kerak"}, {"ar": "لِتَعْلِيمِ النَّاسِ الْعَقِيدَةَ الصَّحِيحَةَ إِلَّا سَلَكْنَاهُ", "uz": "odamlarga to'g'ri aqidani o'rgatish uchun, uni bosib o'tmagunimizcha"}], "full_uz": "Shu bilan birga, odamlarga to'g'ri aqidani o'rgatish uchun hech qanday yo'lni bosib o'tmasdan qoldirmasligimiz kerak.", "note": null},
  {"num": 216, "time": "00:18:13,120 --> 00:18:16,140", "arabic": "وَلَكِنَّهُمْ هُمْ مَنْ يَتَعَرَّضُونَ لَنَا يَا إِمَامُ", "segs": null, "full_uz": "Lekin bizga tegayotgan aynan ular-ku, imom.", "note": null},
  {"num": 217, "time": "00:18:16,140 --> 00:18:18,539", "arabic": "تَحَاشَوْهُمْ مَا اسْتَطَعْتُمْ", "segs": null, "full_uz": "Iloji boricha ulardan chetlaning.", "note": null},
  {"num": 218, "time": "00:18:18,920 --> 00:18:28,900", "arabic": "وَدِدْتُ لَوْ أَنَّ أُمِّي رَحِمَهَا اللَّهُ", "segs": null, "full_uz": "Qani edi, onam — Alloh unga rahm qilsin.", "note": null},
  {"num": 219, "time": "00:18:28,900 --> 00:18:30,779", "arabic": "رَأَتْ حَفِيدَهَا صَالِحًا", "segs": null, "full_uz": "Nabirasi Solihni ko'rsa edi.", "note": null},
  {"num": 220, "time": "00:18:30,779 --> 00:18:33,500", "arabic": "رَحِمَهَا اللَّهُ", "segs": null, "full_uz": "Alloh unga rahm qilsin.", "note": null},
  {"num": 221, "time": "00:18:33,500 --> 00:18:38,720", "arabic": "قَدْ تَرَكَتْ خَيْرَ رَجُلٍ وَخَيْرَ زَوْجٍ وَخَيْرَ أَبٍ", "segs": null, "full_uz": "U eng yaxshi odam, eng yaxshi turmush o'rtoq va eng yaxshi otani orqada qoldirdi.", "note": null},
  {"num": 222, "time": "00:18:38,720 --> 00:18:42,060", "arabic": "أَكَانَتْ أَشَدَّ رَغْبَتِهَا أَنْ تَرَى أَحْفَادَهَا", "segs": null, "full_uz": "Uning eng katta orzusi nabiralarini ko'rish edimi?", "note": null},
  {"num": 223, "time": "00:18:42,060 --> 00:18:47,800", "arabic": "وَلَكِنِ الْحَمْدُ لِلَّهِ قَدَرُ اللَّهِ وَمَا شَاءَ فَعَلَ", "segs": null, "full_uz": "Lekin Allohga hamdlar bo'lsin, Allohning taqdiri shu, va U xohlaganini qildi.", "note": null},
  {"num": 224, "time": "00:18:47,799 --> 00:18:50,180", "arabic": "كَمْ كَانَتْ تَطْلُبُ مِنِّي ذَلِكَ", "segs": null, "full_uz": "U mendan buni qancha marta so'ragan edi.", "note": null},
  {"num": 225, "time": "00:18:50,180 --> 00:18:53,619", "arabic": "وَلَكِنَّنِي لَمْ أُجِبْهَا إِلَى مَا أَرَادَتْ", "segs": null, "full_uz": "Lekin men uning istagiga javob bermagan edim.", "note": null},
  {"num": 226, "time": "00:18:53,619 --> 00:18:57,799", "arabic": "مَا الَّذِي مَنَعَكَ مِنْ أَنْ تُحَقِّقَ رَغْبَتَهَا؟", "segs": null, "full_uz": "Uning istagini ro'yobga chiqarishga nima to'sqinlik qildi?", "note": null},
  {"num": 227, "time": "00:18:59,220 --> 00:18:59,639", "arabic": "اَلْعِلْمُ", "segs": null, "full_uz": "Ilm.", "note": null},
  {"num": 228, "time": "00:18:59,639 --> 00:19:02,379", "arabic": "اَلْعِلْمُ يَا أُمَّ صَالِحٍ", "segs": null, "full_uz": "Ilm, Umm Solih.", "note": null},
  {"num": 229, "time": "00:19:02,379 --> 00:19:04,799", "arabic": "أَخَذَنِي حَتَّى مِنْ نَفْسِي", "segs": null, "full_uz": "U meni o'zimdan ham olib qo'ygan edi.", "note": null},
  {"num": 230, "time": "00:19:05,519 --> 00:19:07,079", "arabic": "فَقَدْ ضَرَبْتُ الْآفَاقَ", "segs": null, "full_uz": "Men ufqlarni kezib chiqdim.", "note": null},
  {"num": 231, "time": "00:19:07,079 --> 00:19:09,779", "arabic": "وَلَمْ أَتْرُكْ شَيْخًا إِلَّا وَرَحَلْتُ إِلَيْهِ", "segs": null, "full_uz": "Va safar qilib bormagan biror shayxni qoldirmadim.", "note": null},
  {"num": 232, "time": "00:19:09,779 --> 00:19:14,180", "arabic": "فَأَيُّ زَوْجَةٍ كَانَتْ لِتَرْضَى بِرُفْقَةِ زَوْجٍ مِثْلِي؟", "segs": null, "full_uz": "Qaysi xotin mendek er bilan yashashga rozi bo'lardi?", "note": null},
  {"num": 233, "time": "00:19:14,180 --> 00:19:15,259", "arabic": "حَسَنًا فَعَلْتَ", "segs": null, "full_uz": "Yaxshi qilding.", "note": null},
  {"num": 234, "time": "00:19:15,259 --> 00:19:20,140", "arabic": "أَتَعْرِفُ لَوْ أَنَّكَ طَلَبْتَنِي لِلزَّوَاجِ وَأَنْتَ فِي حَالِكَ تِلْكَ", "segs": null, "full_uz": "Bilasanmi, agar sen o'sha holingda menga uylanmoqchi bo'lganingda.", "note": null},
  {"num": 235, "time": "00:19:20,140 --> 00:19:25,900", "arabic": "لَمَا كُنْتُ أَرْضَى بِكَ زَوْجًا حَتَّى تَنْفُضَ رَاحَتَيْكَ مِنَ التَّرْحَالِ", "segs": [{"ar": "لَمَا كُنْتُ أَرْضَى بِكَ زَوْجًا", "uz": "Senga xotin bo'lishga rozi bo'lmagan bo'lardim"}, {"ar": "حَتَّى تَنْفُضَ رَاحَتَيْكَ مِنَ التَّرْحَالِ", "uz": "sayohatdan qo'ling to'la yig'ilgan changni qoqib tashlamaguningcha"}], "full_uz": "Sayohatdan qo'ling to'la yig'ilgan changni qoqib tashlamaguningcha, senga xotin bo'lishga rozi bo'lmagan bo'lardim.", "note": null},
  {"num": 236, "time": "00:19:25,900 --> 00:19:32,539", "arabic": "فَكَيْفَ لِي أَنْ أَصْبِرَ عَلَى فِرَاقِ زَوْجٍ فِي مِثْلِ دِينِكَ وَخُلُقِكَ؟", "segs": [{"ar": "فَكَيْفَ لِي أَنْ أَصْبِرَ عَلَى فِرَاقِ زَوْجٍ", "uz": "Endi qanday qilib erdan ayrilishga sabr qilay"}, {"ar": "فِي مِثْلِ دِينِكَ وَخُلُقِكَ؟", "uz": "sendek dinli va axloqli bo'lgan?"}], "full_uz": "Endi qanday qilib sendek dinli va axloqli erdan ayrilishga sabr qilay?", "note": null},
  {"num": 237, "time": "00:19:32,539 --> 00:19:36,579", "arabic": "أَكْرَمَنِي اللَّهُ بِكِ يَا زَوْجَتِي وَرَحِمَ اللَّهُ أُمِّي", "segs": null, "full_uz": "Alloh meni sen bilan mukarram qildi, xotinim, va Alloh onamga rahm qilsin.", "note": null},
  {"num": 238, "time": "00:19:36,579 --> 00:19:38,879", "arabic": "كُنْتُ أَقُولُ لَهَا ذَلِكَ وَلَا تَقْتَنِعُ", "segs": null, "full_uz": "Men bunday derdim, u esa ishonmasdi.", "note": null},
  {"num": 239, "time": "00:19:38,879 --> 00:19:42,339", "arabic": "حَدِّثْنِي عَنْ أُمِّكَ يَا أَبَا عَبْدِ اللَّهِ", "segs": null, "full_uz": "Onang haqida gapirib ber, Abu Abdulloh.", "note": null},
  {"num": 240, "time": "00:19:42,339 --> 00:19:44,900", "arabic": "كَيْفَ كَانَ حَالُهَا مَعَكَ", "segs": null, "full_uz": "Sen bilan qanday munosabatda bo'lardi.", "note": null},
  {"num": 241, "time": "00:19:44,900 --> 00:19:51,400", "arabic": "كَيْفَ رَبَّتْكَ؟ أُرِيدُ أَنْ أَعْرِفَ مَنْ هِيَ الَّتِي أَنْجَبَتْ رَجُلًا كَأَحْمَدَ بْنِ حَنْبَلٍ", "segs": [{"ar": "كَيْفَ رَبَّتْكَ؟", "uz": "seni qanday tarbiya qilgan?"}, {"ar": "أُرِيدُ أَنْ أَعْرِفَ مَنْ هِيَ الَّتِي أَنْجَبَتْ رَجُلًا كَأَحْمَدَ بْنِ حَنْبَلٍ", "uz": "Ahmad ibn Hanbaldek odamni tug'gan ayol kim ekanini bilmoqchiman"}], "full_uz": "Seni qanday tarbiya qilgan? Ahmad ibn Hanbaldek odamni tug'gan ayol kim ekanini bilmoqchiman.", "note": null},
  {"num": 242, "time": "00:19:51,400 --> 00:19:53,540", "arabic": "وَأَنَا ابْنُ عَشْرِ سِنِينَ", "segs": null, "full_uz": "Men o'n yoshli bolaligimda.", "note": null},
  {"num": 243, "time": "00:19:53,540 --> 00:19:59,480", "arabic": "كَانَتْ أُمِّي رَحِمَهَا اللَّهُ تُوقِظُنِي قَبْلَ الْفَجْرِ بِقَلِيلٍ لِأَسْتَعِدَّ لِلصَّلَاةِ", "segs": [{"ar": "كَانَتْ أُمِّي رَحِمَهَا اللَّهُ تُوقِظُنِي قَبْلَ الْفَجْرِ بِقَلِيلٍ", "uz": "Onam — Alloh unga rahm qilsin — meni tongdan sal oldin uyg'otardi"}, {"ar": "لِأَسْتَعِدَّ لِلصَّلَاةِ", "uz": "namozga tayyorlanishim uchun"}], "full_uz": "Onam — Alloh unga rahm qilsin — meni namozga tayyorlanish uchun tongdan sal oldin uyg'otardi.", "note": null},
  {"num": 244, "time": "00:19:59,480 --> 00:20:02,259", "arabic": "ثُمَّ تَذْهَبُ بِي إِلَى الْمَسْجِدِ", "segs": null, "full_uz": "Keyin meni masjidga olib borardi.", "note": null},
  {"num": 245, "time": "00:20:02,259 --> 00:20:04,320", "arabic": "فِي ظُلْمَةِ الطَّرِيقِ", "segs": null, "full_uz": "Yo'lning zulmatida.", "note": null},
  {"num": 246, "time": "00:20:04,320 --> 00:20:07,960", "arabic": "غَيْرَ آبِهَةٍ بِحَرِّ الصَّيْفِ أَوْ بَرْدِ الشِّتَاءِ", "segs": null, "full_uz": "Yoz issig'iga ham, qish sovug'iga ham parvo qilmasdan.", "note": null},
  {"num": 247, "time": "00:20:07,960 --> 00:20:12,900", "arabic": "تَنْتَظِرُنِي خَارِجًا ثُمَّ تَعُودُ بِي إِلَى الْبَيْتِ", "segs": null, "full_uz": "Tashqarida meni kutib turar, keyin uyga olib qaytardi.", "note": null},
  {"num": 248, "time": "00:20:12,900 --> 00:20:15,820", "arabic": "آهٍ عَلَى أُمِّي", "segs": null, "full_uz": "Oh, onajonim!", "note": null},
  {"num": 249, "time": "00:20:15,820 --> 00:20:20,540", "arabic": "وَدِدْتُ لَوْ أَنَّ اللَّهَ مَدَّ بِعُمُرِهَا لِتَرَانَا وَصَالِحًا", "segs": null, "full_uz": "Qani edi, Alloh uning umrini uzaytirib, bizni va Solihni ko'rsa edi.", "note": null},
  {"num": 250, "time": "00:20:20,540 --> 00:20:24,880", "arabic": "أُمِّي كَانَتْ أَجْمَلَ الْأُمَّهَاتِ قَلْبًا", "segs": null, "full_uz": "Onam qalban eng go'zal onalardan edi.", "note": null},
  {"num": 251, "time": "00:20:24,880 --> 00:20:27,660", "arabic": "وَأَحَنَّ الْأُمَّهَاتِ", "segs": null, "full_uz": "Va onalarning eng shafqatlisi.", "note": null},
  {"num": 252, "time": "00:20:27,660 --> 00:20:30,620", "arabic": "حَمَاهَا اللَّهُ", "segs": null, "full_uz": "Alloh uni asrasin.", "note": null},
  {"num": 253, "time": "00:20:30,620 --> 00:20:32,580", "arabic": "حَمَاهَا اللَّهُ", "segs": null, "full_uz": "Alloh uni asrasin.", "note": null},
  {"num": 254, "time": "00:20:35,580 --> 00:20:39,740", "arabic": "وَدِدْتُ لَوْ أَنِّي رَأَيْتُهَا وَتَعَلَّمْتُ مِنْهَا", "segs": null, "full_uz": "Qani edi, men uni ko'rib, undan o'rgansam edi.", "note": null},
  {"num": 255, "time": "00:20:39,740 --> 00:20:44,859", "arabic": "لَوْ رَأَيْتِهَا يَا عَبَّاسَةُ", "segs": null, "full_uz": "Uni ko'rganingda edi, Abbasa.", "note": null},
  {"num": 256, "time": "00:20:44,859 --> 00:20:46,620", "arabic": "أَحْبَبْتِهَا", "segs": null, "full_uz": "Uni sevib qolgan bo'larding.", "note": null},
  {"num": 257, "time": "00:20:46,620 --> 00:20:53,120", "arabic": "وَمَنْ يَجْرُؤُ عَلَى أَنْ يَقِفَ فِي وَجْهِ الْمُعْتَزِلَةِ يَا أَبَا نَصْرٍ؟", "segs": [{"ar": "وَمَنْ يَجْرُؤُ عَلَى أَنْ يَقِفَ فِي وَجْهِ الْمُعْتَزِلَةِ", "uz": "Mu'tazilalarga qarshi turishga kim jur'at etadi"}, {"ar": "يَا أَبَا نَصْرٍ؟", "uz": "Abu Nasr?"}], "full_uz": "Mu'tazilalarga qarshi turishga kim jur'at etadi, Abu Nasr?", "note": null},
  {"num": 258, "time": "00:20:53,120 --> 00:20:58,240", "arabic": "وَمِنْ خَلْفِهِمْ أَمِيرُ الْمُؤْمِنِينَ يَنْصُرُهُمْ وَيَبْسُطُ لَهُمُ الطَّرِيقَ", "segs": null, "full_uz": "Ularning ortida esa mo'minlar amiri turib, ularga yordam bermoqda va yo'l ochib bermoqda.", "note": null},
  {"num": 259, "time": "00:20:58,240 --> 00:21:03,380", "arabic": "غَفَرَ اللَّهُ لَكَ يَا أَبَا زَكَرِيَّا", "segs": null, "full_uz": "Alloh seni mag'firat qilsin, Abu Zakariyo.", "note": null},
  {"num": 260, "time": "00:21:03,380 --> 00:21:05,680", "arabic": "نَحْنُ مَنْ يَقِفُ لَهُمْ", "segs": null, "full_uz": "Ularga qarshi turadigan biz o'zimizmiz.", "note": null},
  {"num": 261, "time": "00:21:05,680 --> 00:21:09,120", "arabic": "وَنَحْنُ مَنْ يَتَصَدَّى لِبِدَعِهِمْ وَضَلَالَاتِهِمْ", "segs": null, "full_uz": "Va ularning bid'at va adashuvlariga qarshi chiqadigan ham biz o'zimizmiz.", "note": null},
  {"num": 262, "time": "00:21:09,740 --> 00:21:16,299", "arabic": "اَلْمُسْلِمُونَ الْآنَ أَنْظَارُهُمْ نَحْوَ الْعُلَمَاءِ مَمْدُودَةٌ", "segs": null, "full_uz": "Hozir musulmonlarning nigohlari olimlarga qadalgan.", "note": null},
  {"num": 263, "time": "00:21:16,299 --> 00:21:20,039", "arabic": "يَنْتَظِرُونَ مِنْهُمْ هِبَّةً فِي وَجْهِ الْبَاطِلِ", "segs": null, "full_uz": "Ulardan botilga qarshi bir jasorat kutishmoqda.", "note": null},
  {"num": 264, "time": "00:21:20,039 --> 00:21:25,519", "arabic": "اَلَّذِي عَمِلَ فِي جَسَدِ الْأُمَّةِ بَعْدَ أَنْ نَخَرَ عِظَامَهَا", "segs": null, "full_uz": "U (botil) ummatning suyaklarini kemirib bo'lgach, uning tanasida ishlay boshlagan.", "note": null},
  {"num": 265, "time": "00:21:25,519 --> 00:21:28,120", "arabic": "كَانَ اللَّهُ فِي عَوْنِ الْعُلَمَاءِ يَا ابْنَ هَانِئٍ", "segs": null, "full_uz": "Alloh olimlarga yordamchi bo'lsin, Ibn Hani'.", "note": null},
  {"num": 266, "time": "00:21:28,120 --> 00:21:31,539", "arabic": "يَقِفُونَ فِي وَجْهِ أَهْلِ الْفِسْقِ وَالضَّلَالِ", "segs": null, "full_uz": "Ular fisq va adashuv ahliga qarshi turishadi.", "note": null},
  {"num": 267, "time": "00:21:31,539 --> 00:21:35,099", "arabic": "فَيَدْخُلُونَ سِجَالًا لَا مَنْجَى مِنْهُ مَعَ الْمَأْمُونِ", "segs": null, "full_uz": "Va shu bilan Ma'mun bilan qutulib bo'lmaydigan bir bahsga kirib qolishadi.", "note": null},
  {"num": 268, "time": "00:21:35,099 --> 00:21:38,779", "arabic": "فَتَقَعُ الْفِتْنَةُ بَيْنَ الرَّعِيَّةِ وَالرَّاعِي", "segs": null, "full_uz": "Shu bilan raiyat va rahbar orasida fitna yuz beradi.", "note": null},
  {"num": 269, "time": "00:21:38,779 --> 00:21:43,039", "arabic": "هَذَا اللَّهُ الْخَلِيفَةُ الْمَأْمُونُ", "segs": null, "full_uz": "Bu — Alloh xalifa Ma'mun.", "note": null},
  {"num": 270, "time": "00:21:43,039 --> 00:21:47,680", "arabic": "لَمْ يَسَعْهُ مَا وَسِعَ أَخَاهُ وَأَبَاهُ مِنْ قَبْلُ", "segs": null, "full_uz": "Otasi va akasiga yetgan narsa, unga yetmadi.", "note": null},
  {"num": 271, "time": "00:21:47,680 --> 00:21:51,379", "arabic": "مَا انْقَطَعَ رَأْسُ أَخِيهِ", "segs": null, "full_uz": "Akasining boshi tanidan uzilgan zahoti.", "note": null},
  {"num": 272, "time": "00:21:51,379 --> 00:21:53,740", "arabic": "حَتَّى شَمَّرَ سَاعِدَيْهِ", "segs": null, "full_uz": "U yenglarini shimarib oldi.", "note": null},
  {"num": 273, "time": "00:21:53,740 --> 00:21:57,180", "arabic": "وَمَدَّ لِأَهْلِ الْبِدَعِ وَالضَّلَالِ يَدَيْهِ", "segs": null, "full_uz": "Va bid'at va adashuv ahliga ikki qo'lini cho'zdi.", "note": null},
  {"num": 274, "time": "00:21:57,180 --> 00:21:59,599", "arabic": "يَا أَبَا نَصْرٍ", "segs": null, "full_uz": "Ey Abu Nasr.", "note": null},
  {"num": 275, "time": "00:21:59,599 --> 00:22:01,639", "arabic": "يَجِبُ أَنْ تَحْذَرَ", "segs": null, "full_uz": "Ehtiyot bo'lishing kerak.", "note": null},
  {"num": 276, "time": "00:22:01,639 --> 00:22:03,519", "arabic": "فَالْعُيُونُ عَلَيْكَ", "segs": null, "full_uz": "Chunki ko'zlar senda.", "note": null},
  {"num": 277, "time": "00:22:03,519 --> 00:22:05,319", "arabic": "لَا فَجَعَنَا اللَّهُ بِكَ", "segs": null, "full_uz": "Alloh bizni sen bilan alamli yo'qotishga duchor qilmasin.", "note": null},
  {"num": 278, "time": "00:22:05,319 --> 00:22:09,720", "arabic": "فَجِيعَتُنَا فِي دِينِنَا وَسُنَّةِ نَبِيِّنَا يَا أَبَا زَكَرِيَّا", "segs": null, "full_uz": "Bizning haqiqiy alamimiz dinimiz va Payg'ambarimiz sunnatida bo'ladi, Abu Zakariyo.", "note": null},
  {"num": 279, "time": "00:22:09,720 --> 00:22:14,539", "arabic": "حِينَ يُصْبِحَانِ مَرْمًى لِأَهْلِ الْبِدَعِ وَالضَّلَالَةِ", "segs": null, "full_uz": "Ular bid'at va adashuv ahlining nishoniga aylanganda.", "note": null},
  {"num": 280, "time": "00:22:14,539 --> 00:22:19,439", "arabic": "فَدَاهُمَا أَبِي وَأُمِّي وَكُلُّ آلِ نَصْرٍ الْخُزَاعِيِّ", "segs": null, "full_uz": "Otam-onam va butun Nasr Xuza'iy oilasi ularga fido bo'lsin.", "note": null},
  {"num": 288, "time": "00:22:20,879 --> 00:22:26,359", "arabic": "لَا بُدَّ مِنَ الْأَمْرِ بِالْمَعْرُوفِ وَالنَّهْيِ عَنِ الْمُنْكَرِ", "segs": null, "full_uz": "Ma'rufga buyurish va munkardan qaytarish shart.", "note": null},
  {"num": 289, "time": "00:22:26,359 --> 00:22:40,979", "arabic": "وَذُكِرَ أَنَّ سَارِقًا رُفِعَ إِلَى أَمِيرِ الْمُؤْمِنِينَ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ فَأَمَرَ بِقَطْعِ يَدِهِ", "segs": [{"ar": "وَذُكِرَ أَنَّ سَارِقًا رُفِعَ إِلَى أَمِيرِ الْمُؤْمِنِينَ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ", "uz": "Rivoyat qilinishicha, bir o'g'ri Amir al-Mo'minin Umar ibn al-Xattobga — Alloh undan rozi bo'lsin — keltirilgan"}, {"ar": "فَأَمَرَ بِقَطْعِ يَدِهِ", "uz": "u uning qo'lini kesishga buyurgan"}], "full_uz": "Rivoyat qilinishicha, bir o'g'ri Amir al-Mo'minin Umar ibn al-Xattobga — Alloh undan rozi bo'lsin — keltirilgan, u uning qo'lini kesishga buyurgan.", "note": null},
  {"num": 291, "time": "00:22:40,979 --> 00:22:46,799", "arabic": "فَقَالَ السَّارِقُ مَهْلًا يَا أَمِيرَ الْمُؤْمِنِينَ، وَاللَّهِ مَا سَرَقْتُ إِلَّا بِقَدَرِ اللَّهِ", "segs": null, "full_uz": "O'g'ri dedi: shoshilmang, Amir al-Mo'minin — Alloh haqi, men faqat Allohning taqdiri bilan o'g'irladim.", "note": null},
  {"num": 293, "time": "00:22:46,799 --> 00:22:53,299", "arabic": "وَهَذَا جَوَابٌ صَحِيحٌ، فَقَالَ عُمَرُ: وَنَحْنُ لَا نَقْطَعُ يَدَكَ إِلَّا بِقَدَرِ اللَّهِ", "segs": null, "full_uz": "Bu — to'g'ri javob. Umar dedi: biz ham qo'lingizni faqat Allohning taqdiri bilan kesamiz.", "note": null},
  {"num": 295, "time": "00:22:53,299 --> 00:23:00,379", "arabic": "فَغَلَبَهُ عُمَرُ رَضِيَ اللَّهُ عَنْهُ، فَالسَّارِقُ سَرَقَ بِقَدَرِ اللَّهِ لَكِنْ لَمْ يَسْرِقْ بِشَرْعِ اللَّهِ", "segs": [{"ar": "فَغَلَبَهُ عُمَرُ رَضِيَ اللَّهُ عَنْهُ", "uz": "Umar — Alloh undan rozi bo'lsin — uni yengdi"}, {"ar": "فَالسَّارِقُ سَرَقَ بِقَدَرِ اللَّهِ لَكِنْ لَمْ يَسْرِقْ بِشَرْعِ اللَّهِ", "uz": "o'g'ri Allohning taqdiri bilan o'g'irladi, ammo Allohning shariati bilan o'g'irlamadi"}], "full_uz": "Umar — Alloh undan rozi bo'lsin — uni yengdi — o'g'ri Allohning taqdiri bilan o'g'irladi, ammo Allohning shariati bilan o'g'irlamadi.", "note": null},
  {"num": 298, "time": "00:23:00,379 --> 00:23:08,779", "arabic": "فَتَبَيَّنَ أَنَّ الِاحْتِجَاجَ بِالْقَدَرِ عَلَى الْمَعَاصِي بَاطِلٌ، وَالِاحْتِجَاجَ عَلَى فَوَاتِ الْمَطْلُوبِ بَاطِلٌ أَيْضًا", "segs": [{"ar": "فَتَبَيَّنَ أَنَّ الِاحْتِجَاجَ بِالْقَدَرِ عَلَى الْمَعَاصِي بَاطِلٌ", "uz": "Shunday qilib, gunohlarga taqdirni bahona qilish botil ekani ma'lum bo'ldi"}, {"ar": "وَالِاحْتِجَاجَ عَلَى فَوَاتِ الْمَطْلُوبِ بَاطِلٌ أَيْضًا", "uz": "istagan narsaning qo'ldan ketishiga bahona qilish ham botildir"}], "full_uz": "Shunday qilib, gunohlarga taqdirni bahona qilish botil ekani ma'lum bo'ldi — istagan narsaning qo'ldan ketishiga bahona qilish ham botildir.", "note": null},
  {"num": 300, "time": "00:23:08,779 --> 00:23:15,740", "arabic": "اِقْرَؤُوا الْقُرْآنَ الْكَرِيمَ جَيِّدًا، اِفْهَمُوا مَقَاصِدَ آيَاتِهِ", "segs": null, "full_uz": "Qur'oni karimni yaxshi o'qing — oyatlarining maqsadlarini tushuning.", "note": null},
  {"num": 302, "time": "00:23:15,740 --> 00:23:26,339", "arabic": "اِفْهَمُوا مَرَامِيَ جُمَلِهِ وَكَلِمَاتِهِ حَتَّى تَتَبَيَّنَ صِدْقَ قَوْلِنَا فِي خَلْقِ الْقُرْآنِ", "segs": null, "full_uz": "Jumla va so'zlarining mo'ljallarini tushuning — toki Qur'onning yaratilishi haqidagi so'zimizning to'g'riligi ayon bo'lsin.", "note": null},
  {"num": 304, "time": "00:23:26,339 --> 00:23:37,519", "arabic": "وَكَلَامُنَا هَذَا أَيُّهَا الْإِخْوَةُ مُؤَيَّدٌ مِنَ الْقُرْآنِ ذَاتِهِ وَمِنْ سُنَّةِ النَّبِيِّ نَفْسِهَا", "segs": null, "full_uz": "Bizning bu so'zimiz, ey birodarlar, Qur'onning o'zi va Payg'ambarning sunnati bilan qo'llab-quvvatlangandir.", "note": null},
  {"num": 307, "time": "00:23:37,519 --> 00:23:45,639", "arabic": "فَنَحْنُ لَا نَأْتِي بِالْكَلَامِ مِنْ عِنْدِ أَنْفُسِنَا كَمَا يَفْعَلُ أَهْلُ الضَّلَالِ وَالْبِدَعِ", "segs": null, "full_uz": "Biz adashuv va bid'at ahli qilganidek, gapni o'zimizdan chiqarmaymiz.", "note": null},
  {"num": 309, "time": "00:23:45,639 --> 00:23:57,679", "arabic": "وَلَا نَأْتِي بِالْكَلَامِ جِزَافًا كَمَنْ فَقَدَ عَقْلَهُ، وَكَذَلِكَ قَوْلُنَا فِي الْقَدَرِ", "segs": null, "full_uz": "Va aqlini yo'qotgan kishidek gapni bo'sh-bekorga aytmaymiz — taqdir haqidagi so'zimiz ham shundaydir.", "note": null},
  {"num": 311, "time": "00:23:57,679 --> 00:24:08,339", "arabic": "وَاعْتِقَادُنَا فِي أَنَّ أَفْعَالَ النَّاسِ لَمْ يَخْلُقْهَا اللَّهُ بَلْ هِيَ مِنْ خَلْقِ الْإِنْسَانِ نَفْسِهِ", "segs": null, "full_uz": "E'tiqodimiz shuki, odamlarning qilmishlarini Alloh yaratmagan — balki ular insonning o'zi yaratganidir.", "note": null},
  {"num": 313, "time": "00:24:08,339 --> 00:24:20,199", "arabic": "هَذِهِ الِاعْتِقَادَاتُ هِيَ اعْتِقَادَاتُ حَقٍّ دَلَّ عَلَيْهَا الْعَقْلُ السَّلِيمُ وَأَيَّدْنَاهَا بِالذِّكْرِ الْحَكِيمِ", "segs": null, "full_uz": "Bu e'tiqodlar — sog'lom aql dalolat qilgan haq e'tiqodlardir, ularni hikmatli Zikr (Qur'on) bilan qo'llab-quvvatladik.", "note": null},
  {"num": 316, "time": "00:24:20,199 --> 00:24:25,759", "arabic": "فَلَا يَغُرَّنَّكُمْ حَدِيثُ الْجَهَلَةِ وَمَزَاعِمُ الْفَسَقَةِ", "segs": null, "full_uz": "Jaholat ahlining gapi va fosiqlarning da'volari sizlarni aldab qo'ymasin.", "note": null},
  {"num": 317, "time": "00:24:25,759 --> 00:24:38,299", "arabic": "مَاذَا تَفْعَلُونَ هُنَا؟ بِالْحَقِيقَةِ يَا إِمَامُ", "segs": [{"ar": "مَاذَا تَفْعَلُونَ هُنَا؟", "uz": "Bu yerda nima qilyapsizlar?"}, {"ar": "بِالْحَقِيقَةِ يَا إِمَامُ", "uz": "Rostini aytsam, imom"}], "full_uz": "Bu yerda nima qilyapsizlar? Rostini aytsam, imom.", "note": null},
  {"num": 319, "time": "00:24:38,299 --> 00:24:46,099", "arabic": "يَا شَيْخَنَا، مَا وُقُوفُكُمْ هُنَاكَ؟", "segs": null, "full_uz": "Ey shayximiz. U yerda nega turibsizlar?", "note": null},
  {"num": 321, "time": "00:24:46,099 --> 00:24:48,399", "arabic": "أَلَمْ أَنْهَكُمْ أَنْ تَقْتَرِبُوا مِنْ هَؤُلَاءِ الْقَوْمِ؟", "segs": null, "full_uz": "Sizlarga shu qavmga yaqinlashishni man qilmaganmidim?", "note": null},
  {"num": 322, "time": "00:24:48,399 --> 00:24:50,119", "arabic": "كَانَ وُقُوفُنَا عَرَضًا يَا شَيْخُ", "segs": null, "full_uz": "To'xtashimiz tasodifiy edi, shayx.", "note": null},
  {"num": 323, "time": "00:24:50,119 --> 00:24:52,480", "arabic": "عَرَضًا؟ بَلْ مَرَضًا", "segs": null, "full_uz": "Tasodifiymi? Yo'q, kasallik!", "note": null},
  {"num": 324, "time": "00:24:52,480 --> 00:24:54,199", "arabic": "يَا شَيْخَنَا سَامِحْنَا", "segs": null, "full_uz": "Shayximiz, bizni kechiring.", "note": null},
  {"num": 326, "time": "00:24:54,199 --> 00:25:04,099", "arabic": "أَعْرِضُ عَلَيْكَ أَنْ تَتَوَلَّى الْوِزَارَةَ لِأَمِيرِ الْمُؤْمِنِينَ يَا أَبَا مَعْنٍ، فَلَيْسَ هُنَاكَ أَفْضَلُ وَلَا أَعْقَلُ مِنْكَ لِهَكَذَا مَنْصِبٍ", "segs": [{"ar": "أَعْرِضُ عَلَيْكَ أَنْ تَتَوَلَّى الْوِزَارَةَ لِأَمِيرِ الْمُؤْمِنِينَ يَا أَبَا مَعْنٍ", "uz": "Senga Amir al-Mo'minin uchun vazirlikni taklif qilaman, Abu Ma'n"}, {"ar": "فَلَيْسَ هُنَاكَ أَفْضَلُ وَلَا أَعْقَلُ مِنْكَ لِهَكَذَا مَنْصِبٍ", "uz": "bunday mansab uchun sendan yaxshiroq va aqllirog'i yo'q"}], "full_uz": "Senga Amir al-Mo'minin uchun vazirlikni taklif qilaman, Abu Ma'n — bunday mansab uchun sendan yaxshiroq va aqllirog'i yo'q.", "note": null},
  {"num": 328, "time": "00:25:04,779 --> 00:25:11,439", "arabic": "أَشْكُرُ لِأَمِيرِ الْمُؤْمِنِينَ ثِقَتَهُ وَحُسْنَ رَأْيِهِ بِخَادِمِهِ ثُمَامَةَ بْنِ الْأَشْرَسِ", "segs": null, "full_uz": "Amir al-Mo'mininning xizmatkori Sumoma ibn al-Ashrasga bo'lgan ishonchi va yaxshi fikri uchun minnatdorchilik bildiraman.", "note": null},
  {"num": 329, "time": "00:25:11,440 --> 00:25:22,440", "arabic": "وَلَكِنْ إِنْ رَأَى أَمِيرُ الْمُؤْمِنِينَ أَنْ يُعْفِيَنِي مِنْ ذَلِكَ، لِمَاذَا؟", "segs": null, "full_uz": "Ammo Amir al-Mo'minin mendan buni ma'zur ko'rsa. Nega?", "note": null},
  {"num": 332, "time": "00:25:23,039 --> 00:25:26,440", "arabic": "أَيَرْفُضُ أَحَدٌ وِزَارَةَ أَمِيرِ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Amir al-Mo'mininning vazirligini kimdir rad etadimi?", "note": null},
  {"num": 333, "time": "00:25:27,200 --> 00:25:30,279", "arabic": "إِنَّ الْأُمَرَاءَ يَتَسَابَقُونَ عَلَى مَنْصِبٍ كَهَذَا", "segs": null, "full_uz": "Amirlar bunday mansabga erishish uchun poyga qilishadi.", "note": null},
  {"num": 334, "time": "00:25:30,279 --> 00:25:37,019", "arabic": "فَلِمَ الرَّفْضُ إِذَنْ؟", "segs": null, "full_uz": "Unda nega rad etyapsan?", "note": null},
  {"num": 336, "time": "00:25:37,019 --> 00:25:45,480", "arabic": "شَرَحْتُ لَهُ أَسْبَابِي وَبَيَّنْتُ لَهُ حُجَّتِي، إِنِّي أَسْمَعُكَ يَا أَبَا مَعْنٍ", "segs": null, "full_uz": "Unga sabablarimni tushuntirdim va dalilimni bayon qildim. Eshityapman, Abu Ma'n.", "note": null},
  {"num": 338, "time": "00:25:45,480 --> 00:25:52,620", "arabic": "ذَلِكَ أَنِّي رَأَيْتُ أَنَّ كُلَّ مَنْ تَوَلَّى الْوِزَارَةَ يَا مَوْلَايَ أَفْضَتْ بِهِ إِلَى الْهَلَاكِ", "segs": null, "full_uz": "Sababi shuki, xo'jayinim, vazirlikni qabul qilgan har bir kishi halokatga yuz tutganini ko'rganman.", "note": null},
  {"num": 340, "time": "00:26:06,579 --> 00:26:12,259", "arabic": "إِلَى الْهَلَاكِ، كَيْفَ؟", "segs": null, "full_uz": "Halokatga. Qanday qilib?", "note": null},
  {"num": 342, "time": "00:26:12,259 --> 00:26:18,480", "arabic": "اَلْعَاقِلُ مَنِ اتَّعَظَ بِغَيْرِهِ يَا أَمِيرَ الْمُؤْمِنِينَ، وَالْأَحْمَقُ مَنِ اتَّعَظَ بِنَفْسِهِ", "segs": null, "full_uz": "Aqlli kishi — boshqalardan ibrat oladigan, ey Amir al-Mo'minin, ahmoq esa — faqat o'zidan ibrat oladigandir.", "note": null},
  {"num": 344, "time": "00:26:18,480 --> 00:26:25,600", "arabic": "ذَلِكَ أَنِّي رَأَيْتُ نِهَايَةَ وُزَرَاءِ أَبِيكَ وَأَخِيكَ رَحِمَهُمُ اللَّهُ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Sababi shuki, otangiz va akangizning — Alloh ularga rahmat qilsin — vazirlarining oxirini ko'rganman, Amir al-Mo'minin.", "note": null},
  {"num": 346, "time": "00:26:25,600 --> 00:27:02,980", "arabic": "إِنِّي أُفَضِّلُ أَنْ أَعِيشَ عَلَى وَجْهِ الْأَرْضِ خَادِمًا مِنْ أَنْ أَسْكُنَ بَاطِنَهَا مَلِكًا", "segs": null, "full_uz": "Men yer yuzida xizmatkor bo'lib yashashni, uning ostida podshoh bo'lib yotishdan afzal ko'raman.", "note": null},
  {"num": 349, "time": "00:27:03,000 --> 00:27:07,500", "arabic": "قَالَ: فَكَانَ أَحَبَّهُمَا إِلَيْهِ عُمَرُ بْنُ الْخَطَّابِ", "segs": null, "full_uz": "Dedi: ikkovidan unga eng suyuklisi Umar ibn al-Xattob edi.", "note": null},
  {"num": 350, "time": "00:27:07,500 --> 00:27:12,839", "arabic": "أَحَقًّا فَعَلْتَ ذَلِكَ يَا أَبَا عَبْدِ الرَّحْمَنِ؟", "segs": null, "full_uz": "Rostdan shunday qildingmi, Abu Abd ar-Rahmon?", "note": null},
  {"num": 351, "time": "00:27:12,839 --> 00:27:20,039", "arabic": "أَجَلْ، أَمْ تَظُنُّ أَنِّي سَأَتْرُكُ أَحَدَ أَبْنَائِنَا يُعَانِي الْفَاقَةَ وَالْعَوَزَ وَأَنَا أَسْتَطِيعُ نَفْعَهُ؟", "segs": [{"ar": "أَجَلْ، أَمْ تَظُنُّ أَنِّي سَأَتْرُكُ أَحَدَ أَبْنَائِنَا يُعَانِي الْفَاقَةَ وَالْعَوَزَ", "uz": "Ha — yoki farzandlarimizdan birini faqirlik va muhtojlikda qiynalishga qo'yib beraman deb o'ylaysanmi"}, {"ar": "وَأَنَا أَسْتَطِيعُ نَفْعَهُ؟", "uz": "yordam berish qo'limdan kelib turib?"}], "full_uz": "Ha — yoki farzandlarimizdan birini yordam berish qo'limdan kelib turib, faqirlik va muhtojlikda qiynalishga qo'yib beraman deb o'ylaysanmi?", "note": null},
  {"num": 352, "time": "00:27:20,039 --> 00:27:23,720", "arabic": "إِنَّ إِعَانَتَكَ وَمُوَاسَاتَكَ فَرْضٌ عَلَيْهِ", "segs": null, "full_uz": "Sening unga yordam va tasalli berishing farzdir.", "note": null},
  {"num": 353, "time": "00:27:23,720 --> 00:27:26,140", "arabic": "وَمَاذَا تَرَى أَنْ أُقَابِلَ أَمِيرَ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Amir al-Mo'minin bilan uchrashishimni qanday deb bilasan?", "note": null},
  {"num": 354, "time": "00:27:26,140 --> 00:27:33,400", "arabic": "فِي أَيِّ وَقْتٍ تَشَاءُ، فَقَطْ قُلْ لِلْحَاجِبِ إِنَّكَ مِنْ قِبَلِي وَسَتَرَى الْحَفَاوَةَ الَّتِي سَيَلْقَاكَ بِهَا", "segs": null, "full_uz": "Xohlagan vaqtingda — faqat farroshga mendan ekaningni ayt, seni qanday izzat-hurmat bilan qarshi olishini ko'rasan.", "note": null},
  {"num": 356, "time": "00:27:33,400 --> 00:27:36,680", "arabic": "جَزَاكَ اللَّهُ خَيْرًا يَا شَيْخَنَا، جَزَاكَ اللَّهُ خَيْرًا", "segs": null, "full_uz": "Alloh sizga yaxshilik bersin, shayximiz. Alloh sizga yaxshilik bersin.", "note": null},
  {"num": 358, "time": "00:27:36,680 --> 00:27:43,420", "arabic": "وَاحْرِصْ إِنْ عَرَضَ عَلَيْكَ أَمِيرُ الْمُؤْمِنِينَ عَمَلًا أَنْ يَكُونَ عَمَلًا قَرِيبًا مِنْهُ", "segs": null, "full_uz": "Agar Amir al-Mo'minin senga bir ish taklif qilsa, uning yaqinida bo'ladigan ish bo'lishiga alohida e'tibor ber.", "note": null},
  {"num": 360, "time": "00:27:43,420 --> 00:27:56,020", "arabic": "نُرِيدُ أَنْ يَكُونَ كُلُّ مَنْ حَوْلَهُ مِنْ أَبْنَائِنَا، لَا نُرِيدُ لِأُذُنِهِ أَنْ تَسْمَعَ مِنْ غَيْرِنَا كَمَا لَا نُرِيدُ لِأُذُنِ غَيْرِنَا أَنْ تَسْمَعَ مِنْهُ", "segs": [{"ar": "نُرِيدُ أَنْ يَكُونَ كُلُّ مَنْ حَوْلَهُ مِنْ أَبْنَائِنَا", "uz": "Uning atrofidagilarning barchasi bizning farzandlarimizdan bo'lishini istaymiz"}, {"ar": "لَا نُرِيدُ لِأُذُنِهِ أَنْ تَسْمَعَ مِنْ غَيْرِنَا", "uz": "qulog'i bizdan boshqasidan eshitishini istamaymiz"}, {"ar": "كَمَا لَا نُرِيدُ لِأُذُنِ غَيْرِنَا أَنْ تَسْمَعَ مِنْهُ", "uz": "boshqalarning qulog'i undan eshitishini ham istamaymiz"}], "full_uz": "Uning atrofidagilarning barchasi bizning farzandlarimizdan bo'lishini istaymiz — qulog'i bizdan boshqasidan eshitishini istamaymiz, boshqalarning qulog'i undan eshitishini ham istamaymiz.", "note": null},
  {"num": 363, "time": "00:27:56,020 --> 00:28:04,340", "arabic": "فَهِمْتُ ذَلِكَ، أَمِيرُ الْمُؤْمِنِينَ حَفِظَهُ اللَّهُ", "segs": null, "full_uz": "Tushundim. Amir al-Mo'minin, Alloh uni asrasin.", "note": null},
  {"num": 365, "time": "00:28:04,340 --> 00:28:11,860", "arabic": "وَإِنْ كَانَ يَقِفُ إِلَى صَفِّنَا إِلَّا أَنَّ قُلُوبَ السَّلَاطِينِ كَسَمَاءِ الْخَرِيفِ", "segs": null, "full_uz": "Bizning safimizda tursa-da, sultonlarning qalbi kuz osmoni kabidir.", "note": "قُلُوبُ السَّلَاطِينِ كَسَمَاءِ الْخَرِيفِ — hukmdorlarning ko'ngli o'zgaruvchan bo'lishini bildiruvchi majoziy ibora."},
  {"num": 367, "time": "00:28:11,860 --> 00:28:19,880", "arabic": "لَا يُعْرَفُ مَتَى تَتَلَبَّدُ بِالْغُيُومِ، سَيَرَى أَمِيرُ الْمُؤْمِنِينَ مَا يُرْضِيهِ", "segs": null, "full_uz": "Qachon bulut bilan qoplanishi noma'lum. Amir al-Mo'minin o'zini rozi qiladigan narsani ko'radi.", "note": null},
  {"num": 369, "time": "00:28:19,880 --> 00:28:23,740", "arabic": "وَمَا يُرْضِيكَ يَا شَيْخُ", "segs": null, "full_uz": "Va sizni rozi qiladigan narsani ham, shayx.", "note": null},
  {"num": 370, "time": "00:28:23,740 --> 00:28:31,440", "arabic": "كَيْفَ حَالُكَ يَا حَنْبَلُ؟ بِخَيْرٍ يَا عَمِّ", "segs": null, "full_uz": "Holing qanday, Hanbal? Yaxshi, tog'a.", "note": null},
  {"num": 372, "time": "00:28:31,440 --> 00:28:35,019", "arabic": "يَا عَمِّ؟ حَنْبَلُ! قُلْ يَا إِمَامُ", "segs": null, "full_uz": "Tog'ami? Hanbal! Ayt: imom, de.", "note": null},
  {"num": 373, "time": "00:28:35,019 --> 00:28:37,500", "arabic": "بَارَكَ اللَّهُ فِيكَ كَبُرَ اللَّهُ لَكَ بِهِ", "segs": null, "full_uz": "Alloh senga barakot bersin, Alloh bu bilan senga ulug'lik bersin.", "note": null},
  {"num": 374, "time": "00:28:37,500 --> 00:28:45,240", "arabic": "أَعْلَمُ أَنِّي مُقَصِّرٌ فِي حَقِّكَ وَمَعَ ذَلِكَ جِئْتُكَ بِحَنْبَلٍ أُرِيدُهُ أَنْ يَطْلُبَ الْعِلْمَ عَلَى يَدَيْكَ", "segs": [{"ar": "أَعْلَمُ أَنِّي مُقَصِّرٌ فِي حَقِّكَ", "uz": "Bilaman, sizning haqingizda kamchilik qilganman"}, {"ar": "وَمَعَ ذَلِكَ جِئْتُكَ بِحَنْبَلٍ أُرِيدُهُ أَنْ يَطْلُبَ الْعِلْمَ عَلَى يَدَيْكَ", "uz": "shunga qaramay, Hanbalni sizga olib keldim, u ilmni siz orqali izlashini istayman"}], "full_uz": "Bilaman, sizning haqingizda kamchilik qilganman — shunga qaramay, Hanbalni sizga olib keldim, u ilmni siz orqali izlashini istayman.", "note": null},
  {"num": 376, "time": "00:28:45,240 --> 00:28:47,180", "arabic": "وَهُوَ رَاغِبٌ فِي ذَلِكَ أَيْضًا", "segs": null, "full_uz": "U ham buni istayapti.", "note": null},
  {"num": 377, "time": "00:28:48,299 --> 00:28:52,120", "arabic": "أَهْلًا بِابْنِ عَمِّي حَنْبَلٍ، يَجِبُ أَنْ أَرُدَّ بَعْضَ جَمِيلِكَ", "segs": null, "full_uz": "Amakivachcham Hanbalga xush kelibsan. Sizning yaxshiligingizga qisman javob berishim kerak.", "note": null},
  {"num": 379, "time": "00:28:52,120 --> 00:28:57,720", "arabic": "فَلَنْ أَنْسَى فَضْلَكَ عَلَيَّ وَأَدْعُو اللَّهَ أَنْ يَكُونَ ذُخْرًا لَكَ فِي الْأُولَى وَالْآخِرَةِ", "segs": null, "full_uz": "Menga qilgan ehsoningizni unutmayman va Allohdan bu dunyo va oxiratda sizga zahira bo'lishini so'rayman.", "note": null},
  {"num": 381, "time": "00:28:57,720 --> 00:28:59,700", "arabic": "بَارَكَ اللَّهُ فِيكَ يَا إِمَامُ", "segs": null, "full_uz": "Alloh senga barakot bersin, imom.", "note": null},
  {"num": 382, "time": "00:28:59,700 --> 00:29:04,559", "arabic": "كَمْ تَعِبْتَ يَا أَحْمَدُ فِي هَذَا السَّبِيلِ؟ سَبِيلِ الْعِلْمِ", "segs": null, "full_uz": "Bu yo'lda qancha charchading, Ahmad? Ilm yo'lida.", "note": null},
  {"num": 384, "time": "00:29:04,559 --> 00:29:10,899", "arabic": "حَتَّى مَنَّ اللَّهُ عَلَيْكَ بِمَا تُرِيدُ وَمَا أَرَادَتْ لَكَ أُمُّكَ رَحِمَهَا اللَّهُ", "segs": null, "full_uz": "Toki Alloh senga istagan narsangni va onang — Alloh unga rahmat qilsin — senga istagan narsani ne'mat qilib berdi.", "note": null},
  {"num": 386, "time": "00:29:10,899 --> 00:29:15,720", "arabic": "رَحِمَهَا اللَّهُ", "segs": null, "full_uz": "Alloh unga rahmat qilsin.", "note": null},
  {"num": 387, "time": "00:29:15,720 --> 00:29:23,319", "arabic": "وَيَبْدُو أَنَّ ابْنَ عَمِّكَ حَنْبَلَ يَقْتَفِي أَثَرَكَ وَيَتَّخِذُ مِنْكَ مِثَالًا وَقُدْوَةً", "segs": null, "full_uz": "Ko'rinishidan, amakivachchang Hanbal seni izlab, seni misol va o'rnak qilib olibdi.", "note": null},
  {"num": 389, "time": "00:29:23,319 --> 00:29:30,639", "arabic": "قُدْوَتُنَا جَمِيعًا فِي هَذَا الْعِلْمِ وَالْفِقْهِ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Bu ilm va fiqhda hammamizning o'rnagimiz — Muhammad ibn Abdulloh sollallohu alayhi va sallamdir.", "note": null},
  {"num": 391, "time": "00:29:30,639 --> 00:29:35,839", "arabic": "صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، رَأَيْتُ فِي ابْنِ عَمِّكَ وَلَعًا بِالْعِلْمِ", "segs": null, "full_uz": "Sollallohu alayhi va sallam. Amakivachchangda ilmga ishtiyoq ko'rdim.", "note": null},
  {"num": 393, "time": "00:29:35,839 --> 00:29:42,599", "arabic": "فَقُلْتُ فِي نَفْسِي مَا دَامَتْ هَذِهِ رَغْبَتَهُ وَشَيْخُ بَغْدَادَ ابْنُ عَمِّهِ فَقَدْ كُفِينَا الْمَؤُونَةَ", "segs": null, "full_uz": "O'zimga dedim — bu uning istagi bo'lar ekan, Bag'dodning shayxi esa uning amakivachchasi bo'lsa, mashaqqatdan qutuldik.", "note": null},
  {"num": 395, "time": "00:29:42,599 --> 00:29:47,759", "arabic": "عَلَى الرُّحْبِ وَالسَّعَةِ بِآلِ حَنْبَلٍ جَمِيعًا، وَلَكِنْ أَخْبِرْنِي يَا عَمِّ", "segs": null, "full_uz": "Hanbal oilasining barchasiga keng joy va hush kelibsiz. Ammo ayting menga, tog'a.", "note": null},
  {"num": 397, "time": "00:29:47,759 --> 00:29:50,519", "arabic": "هَلْ أَتَمَّ حَنْبَلٌ حِفْظَ الْقُرْآنِ الْكَرِيمِ؟", "segs": null, "full_uz": "Hanbal Qur'oni karimni yodlashni tugatdimi?", "note": null},
  {"num": 398, "time": "00:29:50,519 --> 00:29:54,139", "arabic": "فِي الْحَقِيقَةِ لَمْ يَنْتَهِ بَعْدُ حَنْبَلٌ مِنْ حِفْظِ الْقُرْآنِ", "segs": null, "full_uz": "Haqiqatda, Hanbal hali Qur'onni yodlashni tugatmagan.", "note": null},
  {"num": 399, "time": "00:29:54,139 --> 00:29:56,019", "arabic": "لَكِنَّهُ يُشْرِفُ عَلَى ذَلِكَ", "segs": null, "full_uz": "Ammo unga yaqinlashib qolgan.", "note": null},
  {"num": 400, "time": "00:29:56,019 --> 00:29:59,400", "arabic": "أَحْسِبُ أَنَّهُ حَفِظَ عِشْرِينَ جُزْءًا مِنْهُ", "segs": null, "full_uz": "O'ylashimcha, undan yigirma juzni yodlagan.", "note": null},
  {"num": 401, "time": "00:29:59,400 --> 00:30:05,480", "arabic": "بَلِ اثْنَيْنِ وَعِشْرِينَ، وَدَقِيقٌ أَيْضًا، بَارَكَ اللَّهُ فِيكَ يَا حَنْبَلُ", "segs": null, "full_uz": "Yo'q, yigirma ikkitasini — va aniq ham. Alloh senga barakot bersin, Hanbal.", "note": null},
  {"num": 404, "time": "00:30:05,480 --> 00:30:11,619", "arabic": "اِسْمَعْ يَا أَخِي، حِفْظُ الْقُرْآنِ الْكَرِيمِ مُقَدَّمٌ عَلَى حِفْظِ الْحَدِيثِ الشَّرِيفِ", "segs": null, "full_uz": "Eshit, birodarim — Qur'oni karimni yodlash sharif hadisni yodlashdan muqaddamdir.", "note": null},
  {"num": 406, "time": "00:30:11,619 --> 00:30:16,259", "arabic": "فَمَتَى انْتَهَيْتَ مِنْ حِفْظِ الْقُرْآنِ الْكَرِيمِ فَاحْمِلْ قَرَاطِيسَكَ وَاحْضُرْ إِلَى دَارِي", "segs": null, "full_uz": "Qur'oni karimni yodlashni tugatganingda, qog'ozlaringni olib, uyimga kel.", "note": null},
  {"num": 408, "time": "00:30:16,259 --> 00:30:18,019", "arabic": "فَأَنَا فِي انْتِظَارِكَ، أَفَهِمْتَ؟", "segs": null, "full_uz": "Men seni kutaman. Tushundingmi?", "note": null},
  {"num": 410, "time": "00:30:18,019 --> 00:30:18,440", "arabic": "أَجَلْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 411, "time": "00:30:18,440 --> 00:30:21,859", "arabic": "بَارَكَ اللَّهُ فِيكَ، شُكْرًا", "segs": null, "full_uz": "Alloh senga barakot bersin. Rahmat.", "note": null},
  {"num": 413, "time": "00:30:49,859 --> 00:30:55,279", "arabic": "مَنْ هَذَا الرَّجُلُ؟ إِنَّهُ الْبَهْلُولُ أَعَزَّكَ اللَّهُ", "segs": null, "full_uz": "Bu kim o'zi? Bu — al-Bahlul, Alloh sizni aziz qilsin.", "note": null},
  {"num": 415, "time": "00:30:55,279 --> 00:31:04,439", "arabic": "أُرِيدُ أَنْ أُكَلِّمَهُ، لَا تَفْعَلْ ذَلِكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Uni bilan gaplashmoqchiman. Buni qilmang, xo'jayinim.", "note": null},
  {"num": 417, "time": "00:31:04,439 --> 00:31:08,059", "arabic": "لِمَاذَا؟ لِأَنَّهُ بَهْلُولٌ", "segs": null, "full_uz": "Nega? Chunki u al-Bahlul.", "note": null},
  {"num": 419, "time": "00:31:08,059 --> 00:31:13,539", "arabic": "وَمَا الضَّيْرُ فِي ذَلِكَ يَا ابْنَ أَكْثَمَ؟ مَوْلَايَ أَنْتَ تَعْرِفُ شَطَحَاتِ الْبَهْلُولِ", "segs": null, "full_uz": "Bundan nima zarar bor, Ibn Aksam? Xo'jayinim, siz al-Bahlulning g'alati gaplarini bilasiz-ku.", "note": null},
  {"num": 421, "time": "00:31:13,539 --> 00:31:16,559", "arabic": "لِأَنَّنِي أَعْرِفُهَا أُرِيدُ أَنْ أُكَلِّمَهُ", "segs": null, "full_uz": "Aynan uni bilganim uchun ham u bilan gaplashmoqchiman.", "note": null},
  {"num": 422, "time": "00:31:16,559 --> 00:31:17,500", "arabic": "اِتْبَعْنِي", "segs": null, "full_uz": "Menga ergash.", "note": null},
  {"num": 423, "time": "00:31:17,500 --> 00:31:28,380", "arabic": "اَلسَّلَامُ عَلَيْكُمْ، وَعَلَيْكُمُ السَّلَامُ", "segs": null, "full_uz": "Assalomu alaykum. Va alaykum assalom.", "note": null},
  {"num": 425, "time": "00:31:28,380 --> 00:31:34,700", "arabic": "أَلَكَ اسْمٌ سِوَى بَهْلُولٍ؟ وَمَا يُفِيدُكَ ذَلِكَ؟", "segs": null, "full_uz": "Bahluldan boshqa isming bormi? Bu senga nima naf beradi?", "note": null},
  {"num": 427, "time": "00:31:34,700 --> 00:31:40,160", "arabic": "اَلْحَقُّ فِيمَا تَقُولُ، إِنَّ الْأَسْمَاءَ لَا تُفِيدُ بِقَدْرِ مَا يُفِيدُ الْمُسَمَّى", "segs": null, "full_uz": "Aytganingda haqiqat bor — ismlar, atalgan narsaning o'zi berganicha naf bermaydi.", "note": null},
  {"num": 429, "time": "00:31:40,160 --> 00:31:46,700", "arabic": "إِذَنْ فَلِمَ تَسْأَلُ عَنِ اسْمِهِ؟", "segs": null, "full_uz": "Unda nega ismini so'rayapsan?", "note": null},
  {"num": 430, "time": "00:31:47,500 --> 00:31:53,500", "arabic": "دَعْكَ مِمَّا لَا يُفِيدُ، كَمْ لَكَ مِنَ السِّنِينَ؟", "segs": null, "full_uz": "Naf bermaydigan narsani qo'y — necha yoshdasan?", "note": null},
  {"num": 432, "time": "00:31:55,259 --> 00:31:58,880", "arabic": "لَيْسَ لِي مِنَ السِّنِينَ شَيْءٌ، كُلُّهَا لِلَّهِ", "segs": null, "full_uz": "Mening yoshim degan narsam yo'q — hammasi Allohniki.", "note": null},
  {"num": 434, "time": "00:31:58,880 --> 00:32:02,500", "arabic": "أَمِيرُ الْمُؤْمِنِينَ يَقْصِدُ كَمْ سِنُّكَ؟", "segs": null, "full_uz": "Amir al-Mo'minin yoshingiz nechada, demoqchi.", "note": null},
  {"num": 436, "time": "00:32:04,980 --> 00:32:08,619", "arabic": "سِنِّي عَظْمٌ", "segs": null, "full_uz": "Yoshim — suyakdir.", "note": null},
  {"num": 438, "time": "00:32:08,619 --> 00:32:11,500", "arabic": "فَابْنُ كَمْ أَنْتَ؟", "segs": null, "full_uz": "Unda nechchi yoshlisan?", "note": null},
  {"num": 439, "time": "00:32:12,259 --> 00:32:15,440", "arabic": "اِبْنُ اثْنَيْنِ، أُمُّهُ وَقَبُّهُ", "segs": null, "full_uz": "Ikkitaning o'g'liman — onasi va bobosi.", "note": null},
  {"num": 441, "time": "00:32:15,440 --> 00:32:18,559", "arabic": "كَمْ أَتَى عَلَيْكَ؟", "segs": null, "full_uz": "Sendan qancha o'tdi?", "note": null},
  {"num": 442, "time": "00:32:18,559 --> 00:32:21,000", "arabic": "لَوْ أَتَى عَلَيَّ شَيْءٌ لَقَتَلَنِي", "segs": null, "full_uz": "Agar mendan biror narsa o'tganida, meni o'ldirar edi.", "note": null},
  {"num": 443, "time": "00:32:21,000 --> 00:32:24,640", "arabic": "فَكَيْفَ إِذَنْ نَقُولُ يَا بَهْلُولُ؟", "segs": null, "full_uz": "Unda qanday deymiz, Bahlul?", "note": null},
  {"num": 444, "time": "00:32:24,640 --> 00:32:32,220", "arabic": "قُولُوا كَمْ مَضَى مِنْ عُمُرِكَ؟ وَأَنَا أُجِيبُ: قَدْ مَضَى الْكَثِيرُ وَلَمْ يَبْقَ إِلَّا الْقَلِيلُ", "segs": null, "full_uz": "«Umringdan qancha o'tdi?» deng — men esa javob beraman: ko'pi o'tdi, ozgina qoldi.", "note": null},
  {"num": 446, "time": "00:32:32,220 --> 00:32:37,220", "arabic": "أَلَمْ أُخْبِرْكَ يَا مَوْلَايَ أَنْ لَا فَائِدَةَ مِنَ الْحَدِيثِ مَعَ الْبَهْلُولِ؟", "segs": null, "full_uz": "Sizga aytmaganmidim, xo'jayinim — al-Bahlul bilan gaplashishning foydasi yo'q, deb?", "note": null},
  {"num": 447, "time": "00:32:37,220 --> 00:32:50,640", "arabic": "كَيْفَ تَرَى أَمِيرَ الْمُؤْمِنِينَ الْمَأْمُونَ فِي عَيْنَيْكَ يَا بَهْلُولُ؟", "segs": null, "full_uz": "Amir al-Mo'minin al-Ma'munni ko'zingda qanday ko'rasan, Bahlul?", "note": null},
  {"num": 448, "time": "00:32:50,640 --> 00:33:01,420", "arabic": "أَتَظُنُّ أَنَّ هَذَا الْمَأْمُونَ يَنْبُلُ فِي عَيْنَيْهِ وَقَدْ قَتَلَ أَخَاهُ؟", "segs": [{"ar": "أَتَظُنُّ أَنَّ هَذَا الْمَأْمُونَ يَنْبُلُ فِي عَيْنَيْهِ؟", "uz": "Bu al-Ma'mun o'z ko'zida ulug' ko'rinadi deb o'ylaysanmi?"}, {"ar": "وَقَدْ قَتَلَ أَخَاهُ؟", "uz": "u akasini o'ldirgan bo'lsa?"}], "full_uz": "Bu al-Ma'mun o'z ko'zida ulug' ko'rinadi deb o'ylaysanmi — u akasini o'ldirgan bo'lsa?", "note": null},
  {"num": 450, "time": "00:33:07,220 --> 00:34:00,160", "arabic": "أَمْسِ", "segs": null, "full_uz": "Kecha.", "note": null},
  {"num": 453, "time": "00:34:07,220 --> 00:34:36,380", "arabic": "مَا هَذَا الْبَلَاءُ الَّذِي نَزَلَ عَلَى الْمُسْلِمِينَ؟", "segs": null, "full_uz": "Musulmonlar ustiga tushgan bu qanday balo o'zi?", "note": null},
  {"num": 454, "time": "00:34:36,380 --> 00:34:43,000", "arabic": "مَاذَا يُرِيدُ هَؤُلَاءِ الْقَوْمُ مِنَ الْخَوْضِ فِي أَحَادِيثَ لَمْ يَخُضْ فِيهَا الرَّسُولُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": [{"ar": "مَاذَا يُرِيدُ هَؤُلَاءِ الْقَوْمُ", "uz": "Bu qavm nima istaydi"}, {"ar": "مِنَ الْخَوْضِ فِي أَحَادِيثَ لَمْ يَخُضْ فِيهَا الرَّسُولُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "uz": "Rasululloh sollallohu alayhi va sallam kirishmagan mavzularga aralashishdan"}], "full_uz": "Bu qavm Rasululloh sollallohu alayhi va sallam ham, uning sahobalari ham kirishmagan mavzularga aralashib nima istaydi.", "note": null},
  {"num": 455, "time": "00:34:43,000 --> 00:34:45,300", "arabic": "وَلَا حَتَّى صَحَابَتُهُ", "segs": null, "full_uz": "Uning sahobalari ham kirishmagan.", "note": null},
  {"num": 456, "time": "00:34:45,300 --> 00:34:56,539", "arabic": "أَيُّ عَقْلٍ أَنْ تَتَحَوَّلَ رِسَالَةُ الْمُسْلِمِينَ مِنْ نَشْرِ الْإِسْلَامِ شَرْقًا وَغَرْبًا إِلَى نَشْرِ الْبِدَعِ وَالضَّلَالَاتِ بَيْنَهُمْ", "segs": [{"ar": "أَيُّ عَقْلٍ أَنْ تَتَحَوَّلَ رِسَالَةُ الْمُسْلِمِينَ مِنْ نَشْرِ الْإِسْلَامِ شَرْقًا وَغَرْبًا", "uz": "Musulmonlarning risolati sharq va g'arbga Islomni tarqatishdan boshqa narsaga aylanishi qanday aqlga sig'adi"}, {"ar": "إِلَى نَشْرِ الْبِدَعِ وَالضَّلَالَاتِ بَيْنَهُمْ", "uz": "ular orasida bid'at va zalolatlarni tarqatishga"}], "full_uz": "Musulmonlarning risolati sharq va g'arbga Islomni tarqatishdan, ular orasida bid'at va zalolatlarni tarqatishga aylanishi qanday aqlga sig'adi.", "note": null},
  {"num": 458, "time": "00:34:56,539 --> 00:35:04,360", "arabic": "مَاذَا يُفِيدُ الْإِسْلَامَ مِنْ كُلِّ تِلْكَ الْمَقُولَاتِ الْبَاطِلَةِ وَالْفَلْسَفَاتِ الْفَارِغَةِ؟", "segs": null, "full_uz": "Bu botil so'zlar va bo'sh falsafalarning barchasi Islomga qanday naf beradi?", "note": null},
  {"num": 460, "time": "00:35:04,360 --> 00:35:12,360", "arabic": "إِنَّمَا يَجْنِيهِ الْمُسْلِمُونَ عَلَى دِينِهِمْ أَشَدَّ ضَرَاوَةً عَلَيْهِ مِنْ صُنْعِ أَعْدَائِهِ بِهِ", "segs": null, "full_uz": "Musulmonlar buni o'z diniga qilishi, dushmanlarining unga qilganidan ham shiddatliroq zarar yetkazadi.", "note": null},
  {"num": 461, "time": "00:35:12,360 --> 00:35:16,360", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "La havla va la quvvata illa billah.", "note": null},
  {"num": 462, "time": "00:35:16,360 --> 00:35:19,360", "arabic": "وَقَالَ اللَّهُ: شَرُّ الْفِتَنِ", "segs": null, "full_uz": "Va Alloh aytdi: fitnalarning eng yomoni.", "note": null},
  {"num": 463, "time": "00:35:26,360 --> 00:35:29,360", "arabic": "أَلَمْ تَنَمْ بَعْدُ يَا أَحْمَدُ؟", "segs": null, "full_uz": "Hali uxlamadingmi, Ahmad?", "note": null},
  {"num": 464, "time": "00:35:29,360 --> 00:35:32,360", "arabic": "نِمْتُ قَلِيلًا أَوَّلَ اللَّيْلِ", "segs": null, "full_uz": "Kechaning boshida bir oz uxladim.", "note": null},
  {"num": 465, "time": "00:35:32,360 --> 00:35:37,599", "arabic": "أَنْتَ تُرْهِقُ نَفْسَكَ، إِنَّ لِبَدَنِكَ عَلَيْكَ حَقًّا", "segs": null, "full_uz": "O'zingni charchatyapsan — badaningning ustingda haqqi bor.", "note": "«لِبَدَنِكَ عَلَيْكَ حَقًّا» — badanning ham o'z haqqi borligi, Payg'ambarimiz sollallohu alayhi va sallamning mashhur so'ziga ishora."},
  {"num": 467, "time": "00:35:37,599 --> 00:35:41,240", "arabic": "وَبَدَنِي قَدْ نَالَ مِنَ الرَّاحَةِ مَا يَكْفِيهِ يَا أُمَّ صَالِحٍ", "segs": null, "full_uz": "Badanim kifoya qiladigan darajada dam oldi, Ummu Solih.", "note": null},
  {"num": 468, "time": "00:35:41,240 --> 00:35:47,140", "arabic": "مَا دَامَ اللَّهُ قَدْ مَنَّ عَلَيَّ بِالصِّحَّةِ وَالْعَافِيَةِ فَلَا أَقَلَّ مِنْ أَنْ أَقُومَ بِحَقِّهِمَا", "segs": null, "full_uz": "Alloh menga sog'liq va salomatlik ne'mat qilib bergan ekan, hech bo'lmasa ularning haqqini ado etishim kerak.", "note": null},
  {"num": 470, "time": "00:35:47,140 --> 00:35:51,900", "arabic": "هَيَّا دَعْكِ مِنَ الْإِشْفَاقِ عَلَيَّ وَتَوَضَّئِي لِصَلَاةِ اللَّيْلِ", "segs": null, "full_uz": "Yur, menga achinishni qo'y va tungi namoz uchun tahorat qil.", "note": null},
  {"num": 471, "time": "00:35:51,900 --> 00:37:02,340", "arabic": "فَقَدْ شَرَفَ اللَّيْلُ عَلَى الِانْقِضَاءِ", "segs": null, "full_uz": "Kecha tugashga yaqinlashdi.", "note": null},
  {"num": 474, "time": "00:37:02,360 --> 00:37:05,800", "arabic": "فِي لِقَاءِ أَمِيرِ الْمُؤْمِنِينَ وَأُعْجِبَ بِكَ", "segs": null, "full_uz": "Amir al-Mo'minin bilan uchrashuvda sizni yoqtirib qoldi.", "note": null},
  {"num": 475, "time": "00:37:05,800 --> 00:37:07,599", "arabic": "أَتَعْلَمُ لِمَاذَا؟", "segs": null, "full_uz": "Bilasizmi, nega?", "note": null},
  {"num": 476, "time": "00:37:07,599 --> 00:37:11,300", "arabic": "لِأَنَّكَ سَيِّدٌ، سَيِّدٌ مُنْذُ وَلَدَتْكَ أُمُّكَ", "segs": null, "full_uz": "Chunki siz sayyidsiz — onangiz sizni tug'ganidan beri sayyidsiz.", "note": null},
  {"num": 478, "time": "00:37:11,300 --> 00:37:17,079", "arabic": "إِنِّي أَتَحَرَّقُ شَوْقًا لِلِقَاءِ أَمِيرِ الْمُؤْمِنِينَ الْمَأْمُونِ", "segs": null, "full_uz": "Amir al-Mo'minin al-Ma'munni uchratishga ishtiyoqim yonib turibdi.", "note": null},
  {"num": 480, "time": "00:37:17,079 --> 00:37:22,140", "arabic": "اَلرَّجُلِ الَّذِي لَمْ نَرَ إِلَّا فِي عَهْدِهِ الْأَمْنَ وَالطُّمَأْنِينَةَ", "segs": null, "full_uz": "Faqat uning davrida xotirjamlik va omonlikni ko'rgan kishimiz.", "note": null},
  {"num": 481, "time": "00:37:22,140 --> 00:37:24,960", "arabic": "وَإِنَّهُ وَلَا أُزَكِّيهِ عَلَى اللَّهِ", "segs": null, "full_uz": "Uni Alloh oldida poklamayman, ammo.", "note": null},
  {"num": 482, "time": "00:37:24,960 --> 00:37:27,960", "arabic": "رَجُلٌ قَلَّ فِي الْخُلَفَاءِ مِثْلُهُ", "segs": null, "full_uz": "Xalifalar orasida uning kabisi kamdan-kamdir.", "note": null},
  {"num": 483, "time": "00:37:27,960 --> 00:37:30,860", "arabic": "هَيَّا بِنَا لَقَدْ تَأَخَّرْنَا يَا رَجُلُ", "segs": null, "full_uz": "Yuring, kechikdik, ey odam.", "note": null},
  {"num": 484, "time": "00:37:30,860 --> 00:37:43,640", "arabic": "وَسُؤْرُ الْكَلْبِ يَخْتَلِفُ حُكْمُهُ عَنْ سُؤْرِ الْهِرِّ", "segs": null, "full_uz": "Itning ortiqchasi (sug'urasi)ning hukmi mushuknikidan farqlanadi.", "note": "اَلسُّؤْر — hayvon ichgan yoki yegan idishda qolgan suv-taom qoldig'i."},
  {"num": 485, "time": "00:37:43,640 --> 00:37:46,140", "arabic": "فَفِي وُلُوغِ الْكَلْبِ فِي الْإِنَاءِ", "segs": null, "full_uz": "It idishga tilini tekkizganda esa.", "note": null},
  {"num": 486, "time": "00:37:46,140 --> 00:37:52,079", "arabic": "رُوِيَ عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ", "segs": null, "full_uz": "Abu Hurayradan, Payg'ambar sollallohu alayhi va sallamdan rivoyat qilinadi, dedilar.", "note": null},
  {"num": 488, "time": "00:37:52,079 --> 00:37:57,220", "arabic": "إِذَا وَلَغَ الْكَلْبُ فِي إِنَاءٍ غُسِلَ سَبْعَ مَرَّاتٍ أُولَاهَا بِالتُّرَابِ", "segs": null, "full_uz": "Agar it idishga tilini tekkizsa, u yetti marta yuviladi, birinchisi tuproq bilan.", "note": "Bu — Muslim rivoyat qilgan mashhur hadis."},
  {"num": 490, "time": "00:37:57,220 --> 00:38:03,639", "arabic": "أَمَّا سُؤْرُ الْهِرِّ فَلَا بَأْسَ بِهِ، فَقَدْ قَالَ النَّبِيُّ عَنِ الْهِرَّةِ: لَيْسَتْ بِنَجَسٍ", "segs": null, "full_uz": "Mushukning ortig'iga esa hech qisi yo'q — Payg'ambar mushuk haqida: «U najas emas», deganlar.", "note": null},
  {"num": 492, "time": "00:38:03,639 --> 00:38:06,880", "arabic": "إِنَّهَا مِنَ الطَّوَّافِينَ عَلَيْكُمْ وَالطَّوَّافَاتِ", "segs": null, "full_uz": "U sizlarning atrofingizda aylanib yuruvchilardan biridir.", "note": "Bu — Tirmiziy va boshqalar rivoyat qilgan mushuklar toza hisoblanishi haqidagi hadis."},
  {"num": 493, "time": "00:38:25,760 --> 00:38:30,099", "arabic": "خَادِمُكَ أَحْمَدُ بْنُ أَبِي دُؤَادٍ الْإِيَادِيُّ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Xizmatkoringiz Ahmad ibn Abi Duvod al-Iyodiy, Amir al-Mo'minin.", "note": null},
  {"num": 494, "time": "00:38:30,099 --> 00:38:34,819", "arabic": "قَدْ أَفَاضَ قَاضِينَا يَحْيَى بْنُ أَكْثَمَ فِي الثَّنَاءِ عَلَيْكَ", "segs": null, "full_uz": "Qozimiz Yahyo ibn Aksam sizni maqtashda mo'l gapirdi.", "note": null},
  {"num": 495, "time": "00:38:34,819 --> 00:38:48,559", "arabic": "أَخْبَرَنِي ابْنُ أَكْثَمَ أَنَّكَ دَرَسْتَ الْفِقْهَ وَتَمَرَّسْتَ فِي صِنَاعَةِ الْكَلَامِ", "segs": null, "full_uz": "Ibn Aksam menga fiqhni o'rganganingiz va kalom san'atida tajriba orttirganingizni aytdi.", "note": null},
  {"num": 496, "time": "00:38:48,559 --> 00:38:52,559", "arabic": "فَعَلَى يَدِ مَنْ طَلَبْتَ الْفِقْهَ؟", "segs": null, "full_uz": "Kim orqali fiqhni talab qildingiz?", "note": null},
  {"num": 497, "time": "00:38:52,559 --> 00:38:54,579", "arabic": "بَدَأْتُ فِي طَلَبِ الْفِقْهِ يَا مَوْلَايَ عَلَى يَدِ الْإِمَامِ هَيَّاجِ بْنِ الْعَلَاءِ السُّلَمِيِّ", "segs": null, "full_uz": "Fiqhni izlashni Imom Hayyoj ibn al-Alo as-Sulamiy orqali boshlagan edim, xo'jayinim.", "note": null},
  {"num": 498, "time": "00:38:54,579 --> 00:39:01,220", "arabic": "صَاحِبِ وَاصِلِ بْنِ عَطَاءٍ", "segs": null, "full_uz": "Vosil ibn Ato'ning sherigi.", "note": null},
  {"num": 500, "time": "00:39:01,220 --> 00:39:08,559", "arabic": "نِعْمَ الْمُعَلِّمُ هُوَ، رَحِمَهُ اللَّهُ وَرَحِمَ اللَّهُ وَاصِلَ بْنَ عَطَاءٍ", "segs": null, "full_uz": "U qanday ajoyib muallim — Alloh unga rahmat qilsin, Alloh Vosil ibn Ato'ga ham rahmat qilsin.", "note": null},
  {"num": 502, "time": "00:39:08,559 --> 00:39:13,360", "arabic": "شَيْخِ الْمُتَكَلِّمِينَ، أَدَامَكَ اللَّهُ يَا مَوْلَايَ", "segs": null, "full_uz": "Kalomchilar shayxi. Alloh sizni davomli qilsin, xo'jayinim.", "note": null},
  {"num": 504, "time": "00:39:13,360 --> 00:39:21,099", "arabic": "مُدَافِعًا عَنْ أَهْلِ الْحَقِّ وَالْعَقْلِ، وَإِنِّي لَأَشْكُرُ اللَّهَ عَزَّ وَجَلَّ الَّذِي حَبَانِي شَرَفَ اللِّقَاءِ بِكَ", "segs": [{"ar": "مُدَافِعًا عَنْ أَهْلِ الْحَقِّ وَالْعَقْلِ", "uz": "Haq va aql ahlining himoyachisi bo'lib"}, {"ar": "وَإِنِّي لَأَشْكُرُ اللَّهَ عَزَّ وَجَلَّ الَّذِي حَبَانِي شَرَفَ اللِّقَاءِ بِكَ", "uz": "Sizga uchrashuv sharafini bergan Alloh azza va jallaga shukr qilaman"}], "full_uz": "Haq va aql ahlining himoyachisi bo'lib. Sizga uchrashuv sharafini bergan Alloh azza va jallaga shukr qilaman.", "note": null},
  {"num": 507, "time": "00:39:21,099 --> 00:39:27,240", "arabic": "وَالْمُثُولِ بَيْنَ يَدَيْكَ فَقَدْ عَقَدْتُ عَلَيْكَ الْآمَالَ بَعْدَ أَنْ وَفَّقَكَ اللَّهُ", "segs": null, "full_uz": "Va sizning huzuringizda turishni — Alloh sizni muvaffaq qilgandan keyin sizga umidlarimni bog'ladim.", "note": null},
  {"num": 510, "time": "00:39:27,239 --> 00:39:33,979", "arabic": "وَحَبَانِي بِأَنْ أَكُونَ خَادِمًا مِنْ خَدَمِكَ، بَارَكَ اللَّهُ فِيكَ أَيُّهَا الْإِيَادِيُّ", "segs": null, "full_uz": "Va sizga xizmatkorlaringizdan biri bo'lish sharafini berdi. Alloh senga barakot bersin, ey Iyodiy.", "note": null},
  {"num": 512, "time": "00:39:33,979 --> 00:39:39,519", "arabic": "يُعْجِبُنِي مِنْكَ طِيبُ الْحَدِيثِ وَدِقَّةُ اللَّفْظِ وَعُمْقُ الْمَعْنَى", "segs": [{"ar": "يُعْجِبُنِي مِنْكَ طِيبُ الْحَدِيثِ", "uz": "Sendagi shirin suhbat meni maftun etadi"}, {"ar": "وَدِقَّةُ اللَّفْظِ وَعُمْقُ الْمَعْنَى", "uz": "va aniq lafz hamda chuqur ma'no"}], "full_uz": "Sendagi shirin suhbat, aniq lafz va chuqur ma'no meni maftun etadi.", "note": null},
  {"num": 513, "time": "00:39:46,439 --> 00:39:52,539", "arabic": "دَعْنِي أَسْأَلْكَ عَنْ رَأْيِكَ فِي الْجَدَلِ الدَّائِرِ فِي أَوْسَاطِ فُقَهَاءِ بَغْدَادَ وَعُلَمَائِهَا", "segs": null, "full_uz": "Menga Bag'dod fuqaho va olimlari orasida yurayotgan bahs haqidagi fikringizni so'rashimga ijozat bering.", "note": null},
  {"num": 514, "time": "00:39:52,539 --> 00:39:56,299", "arabic": "مَوْلَايَ الْمَأْمُونُ يَعْلَمُ أَنَّنِي وَالْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Xo'jayinim al-Ma'mun bilsinlarki, alhamdulillah, men.", "note": null},
  {"num": 515, "time": "00:39:56,300 --> 00:40:01,420", "arabic": "بَعِيدٌ عَمَّا يُغْضِبُ اللَّهَ مِنْ أَنْ يُنْسَبَ التَّجْسِيمُ إِلَيْهِ", "segs": null, "full_uz": "Allohga jismoniylikni nisbat berish kabi Allohni g'azablantiradigan narsadan yiroqman.", "note": null},
  {"num": 516, "time": "00:40:01,420 --> 00:40:05,980", "arabic": "وَمِمَّا يَدَّعِيهِ بَعْضُهُمْ مِنْ جَوَازِ رُؤْيَةِ اللَّهِ فِي الْآخِرَةِ", "segs": null, "full_uz": "Va ba'zilarining oxiratda Allohni ko'rish mumkinligi haqidagi da'volaridan ham.", "note": null},
  {"num": 517, "time": "00:40:05,980 --> 00:40:07,420", "arabic": "أَعَاذَنَا اللَّهُ مِنْ ذَلِكَ", "segs": null, "full_uz": "Alloh bizni undan asrasin.", "note": null},
  {"num": 518, "time": "00:40:07,420 --> 00:40:11,980", "arabic": "كَمَا أَنَّنِي أَسْتَغْفِرُ اللَّهَ مِنْ قَوْلِهِمْ فِي الْقُرْآنِ الْكَرِيمِ", "segs": null, "full_uz": "Shuningdek, ularning Qur'oni karim haqidagi so'zlaridan Allohdan mag'firat so'rayman.", "note": null},
  {"num": 519, "time": "00:40:11,980 --> 00:40:14,940", "arabic": "إِذْ يَقُولُونَ إِنَّهُ لَيْسَ مَخْلُوقًا", "segs": null, "full_uz": "Ular uni yaratilmagan deb aytishadi.", "note": null},
  {"num": 520, "time": "00:40:14,940 --> 00:40:20,480", "arabic": "فَيَضَعُونَهُ بِذَلِكَ مَوْضِعًا لَا يَلِيقُ إِلَّا بِاللَّهِ عَزَّ وَجَلَّ", "segs": null, "full_uz": "Shu bilan uni faqat Alloh azza va jallaga yarashadigan o'ringa qo'yishadi.", "note": null},
  {"num": 521, "time": "00:40:20,480 --> 00:40:27,199", "arabic": "لَكَ مِنَ الْقُرْبَةِ مِنَّا فَوْقَ مَا تُرِيدُ يَا ابْنَ أَبِي دُؤَادٍ", "segs": null, "full_uz": "Sen istagandan ham ko'proq bizga yaqinlik senga tegishlidir, Ibn Abi Duvod.", "note": null},
  {"num": 522, "time": "00:40:45,199 --> 00:40:48,300", "arabic": "بَارَكَ اللَّهُ فِي أَحْمَدَ بْنِ نَصْرٍ الْخُزَاعِيِّ", "segs": null, "full_uz": "Alloh Ahmad ibn Nasr al-Xuzo'iyga barakot bersin.", "note": null},
  {"num": 523, "time": "00:40:48,300 --> 00:40:53,740", "arabic": "نِعْمَ الرَّجُلُ هُوَ، يَصْدَعُ بِالْحَقِّ أَيْنَمَا حَلَّ وَلَا تَأْخُذُهُ فِي اللَّهِ لَوْمَةُ لَائِمٍ", "segs": null, "full_uz": "U qanday ajoyib kishi — qayerda bo'lsa haqni ochiq aytadi, Alloh yo'lida hech kimning koyishi uni to'xtatmaydi.", "note": "«لَا تَأْخُذُهُ فِي اللَّهِ لَوْمَةُ لَائِمٍ» — Moida surasi, 5:54-oyatga ishora."},
  {"num": 525, "time": "00:40:53,740 --> 00:40:58,039", "arabic": "مَا وَجَدْتُ رَجُلًا أَحْنَقَ عَلَى الْمُعْتَزِلَةِ مِنْهُ", "segs": null, "full_uz": "Mo'tazilaga undan ko'ra g'azablanadigan boshqa bir kishini topmadim.", "note": null},
  {"num": 526, "time": "00:40:58,039 --> 00:41:04,380", "arabic": "وَلَوْلَا أَنَّنَا نَتَخَوَّلُهُ بِالنُّصْحِ وَالْمَوْعِظَةِ لَخَشِيتُ أَنْ يَعْمَلَ سَيْفَهُ فِيهِ", "segs": null, "full_uz": "Agar biz uni nasihat va va'z bilan tarbiyalab turmaganimizda, qilichini ishga solishidan qo'rqardim.", "note": "تَخَوَّلَهُ بِالنُّصْحِ — vaqti-vaqti bilan nasihat qilib turish, tarbiyalash."},
  {"num": 528, "time": "00:41:04,380 --> 00:41:07,140", "arabic": "اَلسَّيْفُ مَرْحَلَةُ الْفَصْلِ يَا ابْنَ مَعِينٍ", "segs": null, "full_uz": "Qilich — hal qiluvchi bosqichdir, Ibn Ma'in.", "note": null},
  {"num": 529, "time": "00:41:07,140 --> 00:41:14,519", "arabic": "لِيَنْتَبِهِ الْخُزَاعِيُّ إِلَى نَفْسِهِ فَرُبَّمَا جَرَّ عَمَلُهُ ذَاكَ فِتْنَةً عَلَى الْمُسْلِمِينَ", "segs": [{"ar": "لِيَنْتَبِهِ الْخُزَاعِيُّ إِلَى نَفْسِهِ", "uz": "Al-Xuzo'iy o'zini ehtiyot qilsin"}, {"ar": "فَرُبَّمَا جَرَّ عَمَلُهُ ذَاكَ فِتْنَةً عَلَى الْمُسْلِمِينَ", "uz": "balki uning bu ishi musulmonlarga fitna keltirib chiqarar"}], "full_uz": "Al-Xuzo'iy o'zini ehtiyot qilsin — balki uning bu ishi musulmonlarga fitna keltirib chiqarar.", "note": null},
  {"num": 531, "time": "00:41:14,519 --> 00:41:23,000", "arabic": "أَكْبَرَ مِنْ فِتْنَةِ الْمُعْتَزِلَةِ أَنْفُسِهِمْ، إِنَّهُ رَجُلٌ يَعِزُّ مِثِيلُهُ يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Mo'tazilaning o'zi keltirgan fitnadan ham kattaroq. U tengi kam topiladigan kishidir, Ibn Hanbal.", "note": null},
  {"num": 533, "time": "00:41:23,000 --> 00:41:31,180", "arabic": "نَحْنُ نُرِيدُ أَمْثَالَهُ، فَإِنَّ أَهْلَ الْبَاطِلِ لَا يَرْدَعُهُمْ إِلَّا سَيْفٌ كَسَيْفِ هَذَا الرَّجُلِ", "segs": null, "full_uz": "Biz uning kabilarni istaymiz — botil ahlini faqat shu kishining qilichi kabi qilich to'xtatadi.", "note": null},
  {"num": 535, "time": "00:41:31,180 --> 00:41:41,800", "arabic": "رَجُلٌ سَمِعَ مِنِ ابْنِ عُيَيْنَةَ وَمَالِكِ بْنِ أَنَسٍ وَحَمَّادِ بْنِ زَيْدٍ وَمَعَ ذَلِكَ يَرْفُضُ أَنْ يَتَصَدَّرَ حَلَقَاتِ الدَّرْسِ", "segs": [{"ar": "رَجُلٌ سَمِعَ مِنِ ابْنِ عُيَيْنَةَ وَمَالِكِ بْنِ أَنَسٍ وَحَمَّادِ بْنِ زَيْدٍ", "uz": "Ibn Uyayna, Molik ibn Anas va Hammod ibn Zayddan eshitgan bir kishi"}, {"ar": "وَمَعَ ذَلِكَ يَرْفُضُ أَنْ يَتَصَدَّرَ حَلَقَاتِ الدَّرْسِ", "uz": "shunga qaramay, dars halqalariga boshchilik qilishdan bosh tortadi"}], "full_uz": "Ibn Uyayna, Molik ibn Anas va Hammod ibn Zayddan eshitgan bir kishi — shunga qaramay, dars halqalariga boshchilik qilishdan bosh tortadi.", "note": null},
  {"num": 537, "time": "00:41:41,800 --> 00:41:46,320", "arabic": "لِمَاذَا يَا ابْنَ مَعِينٍ؟ اَلتَّوَاضُعُ", "segs": null, "full_uz": "Nega, Ibn Ma'in? Tavoze'.", "note": null},
  {"num": 539, "time": "00:41:46,320 --> 00:41:52,340", "arabic": "كُلَّمَا سَأَلْتُهُ لِمَاذَا لَا يَتَصَدَّرُ حَلَقَاتِ الدَّرْسِ وَهُوَ مَا هُوَ عَلَيْهِ مِنَ الْعِلْمِ", "segs": null, "full_uz": "Undan nega dars halqalariga boshchilik qilmaydi, o'zi shuncha ilmga ega bo'lsa ham, deb har safar so'raganimda.", "note": null},
  {"num": 540, "time": "00:41:52,340 --> 00:41:55,100", "arabic": "أَجَابَنِي: لَسْتُ أَهْلًا لِذَلِكَ", "segs": null, "full_uz": "Menga: «Men bunga loyiq emasman», deb javob berardi.", "note": null},
  {"num": 541, "time": "00:41:55,100 --> 00:42:00,180", "arabic": "لِلتَّوَاضُعِ مِنْ صِفَاتِ الْأَنْبِيَاءِ وَالصَّالِحِينَ، لَا أُزَكِّيهِ عَلَى اللَّهِ", "segs": null, "full_uz": "Tavoze' — payg'ambarlar va solihlarning sifatlaridandir. Uni Alloh oldida poklamayman.", "note": null},
  {"num": 542, "time": "00:42:00,180 --> 00:42:04,660", "arabic": "يَتَوَاضَعُ عَلَى الرَّغْمِ مِنْ عِلْمِهِ وَإِمَامَتِهِ فِي الْحَدِيثِ", "segs": null, "full_uz": "Ilmi va hadisdagi imomligiga qaramay, tavoze' qiladi.", "note": null},
  {"num": 543, "time": "00:42:04,660 --> 00:42:11,440", "arabic": "وَقَدِ ابْتُلِيَتِ الْأُمَّةُ بِآفَةِ الْفَتْوَى بِدُونِ فِقْهٍ وَالْحَدِيثِ بِدُونِ عِلْمٍ", "segs": null, "full_uz": "Ummat fiqhsiz fatvo va ilmsiz hadis kasalligiga giriftor bo'ldi.", "note": null},
  {"num": 545, "time": "00:42:11,440 --> 00:42:19,719", "arabic": "وَصَدَارَةِ الْمَجَالِسِ بِلَا رَأْيٍ، تَرَى الْوَاحِدَ مِنْهُمْ وَكَأَنَّهُ أَبُو حَنِيفَةَ أَوْ مَالِكُ بْنُ أَنَسٍ أَوِ الشَّافِعِيُّ", "segs": [{"ar": "وَصَدَارَةِ الْمَجَالِسِ بِلَا رَأْيٍ", "uz": "Va fikrsiz majlislarga boshchilik qilish kasalligiga"}, {"ar": "تَرَى الْوَاحِدَ مِنْهُمْ وَكَأَنَّهُ أَبُو حَنِيفَةَ أَوْ مَالِكُ بْنُ أَنَسٍ أَوِ الشَّافِعِيُّ", "uz": "ulardan birortasini xuddi Abu Hanifa, Molik ibn Anas yoki ash-Shofi'iydek ko'rasan"}], "full_uz": "Va fikrsiz majlislarga boshchilik qilish kasalligiga — ulardan birortasini xuddi Abu Hanifa, Molik ibn Anas yoki ash-Shofi'iydek ko'rasan.", "note": null},
  {"num": 547, "time": "00:42:19,719 --> 00:42:22,440", "arabic": "فَيَا لَلْعَجَبِ وَيَا لَلْمُفَارَقَةِ", "segs": null, "full_uz": "Naqadar ajablanarli va naqadar zid holat.", "note": null},
  {"num": 548, "time": "00:42:22,440 --> 00:42:29,019", "arabic": "اَلْحَقُّ أَنَّهُ يُثْنِي عَلَيْكَ كَثِيرًا يَا ابْنَ حَنْبَلٍ، يَبْدُو أَنَّهُ حَضَرَ مَجَالِسَكَ فِي الْمَسْجِدِ الْجَامِعِ", "segs": [{"ar": "اَلْحَقُّ أَنَّهُ يُثْنِي عَلَيْكَ كَثِيرًا يَا ابْنَ حَنْبَلٍ", "uz": "Haqiqatan ham u sizni ko'p maqtaydi, Ibn Hanbal"}, {"ar": "يَبْدُو أَنَّهُ حَضَرَ مَجَالِسَكَ فِي الْمَسْجِدِ الْجَامِعِ", "uz": "ko'rinishidan, jome' masjidida majlislaringizda hozir bo'lgan"}], "full_uz": "Haqiqatan ham u sizni ko'p maqtaydi, Ibn Hanbal — ko'rinishidan, jome' masjidida majlislaringizda hozir bo'lgan.", "note": null},
  {"num": 550, "time": "00:42:29,019 --> 00:42:32,920", "arabic": "فَأَعْجَبَهُ مَا سَمِعَهُ وَرَآهُ فِي حَلَقَاتِ دَرْسِكَ", "segs": null, "full_uz": "Dars halqalaringizda eshitgan va ko'rgan narsasi uni maftun etgan.", "note": null},
  {"num": 551, "time": "00:42:32,920 --> 00:42:37,539", "arabic": "جَزَاهُ اللَّهُ خَيْرًا عَلَى حُسْنِ ظَنِّهِ وَرَفَعَ اللَّهُ لَهُ قَدْرَهُ", "segs": null, "full_uz": "Alloh uning yaxshi gumoni uchun unga yaxshilik bersin va martabasini ko'tarsin.", "note": null},
];

if (typeof module !== "undefined" && module.exports) {
  module.exports = lessons;
}